import type { BankQuestion } from "@/lib/bank";

/** Supreme Court, High Courts and Judicial Review (Indian Polity): 222 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "polity-judiciary-1", "question": "The Supreme Court of India is established under which Article?", "options": ["Article 129", "Article 214", "Article 124", "Article 32"], "answer": 2, "explanation": "Article 124 establishes the Supreme Court and covers the appointment of its judges. Article 214 provides for the High Courts.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-judiciary-2", "question": "The Supreme Court of India was inaugurated on:", "options": ["26 January 1950", "28 January 1950", "15 August 1947", "26 November 1949"], "answer": 1, "explanation": "The Supreme Court was inaugurated on 28 January 1950, two days after the Constitution came into force. It replaced the Federal Court of India.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-3", "question": "A judge of the Supreme Court retires at the age of:", "options": ["62 years", "60 years", "65 years", "70 years"], "answer": 2, "explanation": "Supreme Court judges hold office until 65 (Article 124(2)). High Court judges retire at 62.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-judiciary-4", "question": "A judge of a High Court retires at the age of:", "options": ["62 years", "65 years", "60 years", "58 years"], "answer": 0, "explanation": "Article 217(1) sets 62 as the retirement age for High Court judges. It was raised from 60 by the 15th Amendment (1963).", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-judiciary-5", "question": "High Courts get the power to issue writs from:", "options": ["Article 227", "Article 226", "Article 136", "Article 32"], "answer": 1, "explanation": "Article 226 lets High Courts issue writs. Article 32 is the Supreme Court's writ power, and Article 227 gives High Courts superintendence over the courts below them.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-judiciary-6", "question": "The collegium system for appointing judges came from which case?", "options": ["Kesavananda Bharati case (1973)", "Minerva Mills case (1980)", "S. P. Gupta case (1981)", "Second Judges case (1993)"], "answer": 3, "explanation": "In the Second Judges case (1993), SC Advocates-on-Record Association, the Court read “consultation” with the Chief Justice as “concurrence” and created the collegium. The First Judges case (S. P. Gupta, 1981) had given the executive primacy.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-judiciary-7", "question": "The President can seek the Supreme Court's advisory opinion under:", "options": ["Article 131", "Article 148", "Article 143", "Article 136"], "answer": 2, "explanation": "Article 143 gives the Supreme Court advisory jurisdiction on references from the President. Article 131 is its original jurisdiction, and Article 136 covers special leave to appeal.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-judiciary-8", "question": "Which Article makes the Supreme Court a “court of record”?", "options": ["Article 215", "Article 131", "Article 129", "Article 137"], "answer": 2, "explanation": "Article 129 makes the Supreme Court a court of record with power to punish for contempt of itself. Article 215 does the same for the High Courts.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"polity-judiciary-9","question":"Public Interest Litigation in India is mainly credited to which judges?","options":["P. N. Bhagwati and V. R. Krishna Iyer","Koka Subba Rao and M. Hidayatullah","Y. V. Chandrachud and P. B. Gajendragadkar","A. N. Ray and Y. K. Sabharwal"],"answer":0,"explanation":"Justices P. N. Bhagwati and V. R. Krishna Iyer relaxed the rule on who may sue (locus standi) in the late 1970s and early 1980s, which opened the door to PIL.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · State PSCs"},
  {"id":"polity-judiciary-10","question":"A dispute between the Government of India and a State goes to the Supreme Court under its:","options":["Writ jurisdiction under Article 32","Original jurisdiction under Article 131","Appellate jurisdiction under Article 133","Advisory jurisdiction under Article 143"],"answer":1,"explanation":"Article 131 gives the Supreme Court exclusive original jurisdiction over disputes between the Centre and States, or between States.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-judiciary-11", "question": "On which grounds can a Supreme Court judge be removed?", "options": ["Proved misbehaviour or incapacity", "Any ground the President thinks fit", "Violation of the Constitution", "Loss of confidence of Parliament"], "answer": 0, "explanation": "Article 124(4) allows removal only for proved misbehaviour or incapacity, by an order of the President after an address by both Houses passed by a special majority. “Violation of the Constitution” is the ground for impeaching the President.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-judiciary-12", "question": "How many judges, including the Chief Justice, can the Supreme Court have at present?", "options": ["36", "26", "31", "34"], "answer": 3, "explanation": "The Supreme Court (Number of Judges) Amendment Act, 2019 raised the strength to 33 judges plus the Chief Justice, a total of 34. The original Constitution provided for 7 judges plus the CJI.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"polity-judiciary-13","question":"The 99th Amendment and the NJAC Act it supported were struck down by the Supreme Court in:","options":["1998","2014","2015","1993"],"answer":2,"explanation":"In the Fourth Judges case (October 2015) the Court struck down the 99th Amendment and the NJAC Act as violating judicial independence, a basic feature, and revived the collegium. The trap is 2014, when the Amendment and the Act were passed; 1993 and 1998 are the Second and Third Judges cases that created the collegium.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-14", "question": "The “curative petition” was created by the Supreme Court in:", "options": ["S. R. Bommai v. Union of India", "Rupa Ashok Hurra v. Ashok Hurra", "Maneka Gandhi v. Union of India", "Vishaka v. State of Rajasthan"], "answer": 1, "explanation": "In Rupa Ashok Hurra (2002) the Court allowed a curative petition to correct a gross miscarriage of justice even after a review petition has been dismissed.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-15", "question": "Under which Article does a law declared by the Supreme Court bind all courts in India?", "options": ["Article 144", "Article 137", "Article 141", "Article 142"], "answer": 2, "explanation": "Article 141 makes Supreme Court rulings binding on all courts in India. Article 142 lets the Court pass orders for “complete justice”, and Article 144 requires all authorities to act in aid of the Supreme Court.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-16", "question": "Which Article lets the Supreme Court pass any decree or order needed to do “complete justice” in a case before it?", "options": ["Article 142", "Article 136", "Article 145", "Article 139A"], "answer": 0, "explanation": "Article 142 is the source of the Court's “complete justice” powers, used for example in the Bhopal gas settlement and the Ayodhya judgment.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-judiciary-17","question":"Who appoints ad hoc judges to the Supreme Court when there is no quorum of permanent judges?","options":["The CJI, with the previous consent of the President","The Union Law Minister, in consultation with the CJI","The SC collegium, with the approval of Parliament","The President, on the advice of the Prime Minister"],"answer":0,"explanation":"Under Article 127 the Chief Justice of India, with the previous consent of the President and after consulting the Chief Justice of the High Court concerned, can ask a qualified High Court judge to sit as an ad hoc judge.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-18", "question": "Special leave to appeal against any judgment of any court or tribunal (except military tribunals) is granted under:", "options": ["Article 139", "Article 132", "Article 136", "Article 134"], "answer": 2, "explanation": "Article 136 gives the Supreme Court discretion to grant special leave to appeal from any court or tribunal except those under the armed forces. Articles 132–134 cover regular appeals in constitutional, civil and criminal cases.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-19","question":"A High Court judge is transferred from one High Court to another by the:","options":["President, after consulting the Chief Justice of India","Chief Justice of India alone, on the collegium's advice","Governor of the receiving State, on the CJI's advice","Collegium of the High Court from which he is moved"],"answer":0,"explanation":"Article 222 lets the President transfer a High Court judge after consulting the Chief Justice of India. Since the Third Judges case, the CJI's opinion is formed with a collegium of senior judges.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-20", "question": "According to the Third Judges case (1998), the collegium that recommends Supreme Court appointments consists of the CJI and:", "options": ["the four senior-most judges", "all judges of the Supreme Court", "the three senior-most judges", "the two senior-most judges"], "answer": 0, "explanation": "The 1998 Presidential reference expanded the collegium to the CJI and the four senior-most puisne judges for Supreme Court appointments. For High Court appointments it is the CJI and the two senior-most judges.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-21", "question": "Part XIV-A, which allows administrative tribunals (Article 323A), was added by the:", "options": ["24th Amendment", "42nd Amendment", "44th Amendment", "52nd Amendment"], "answer": 1, "explanation": "The 42nd Amendment (1976) inserted Part XIV-A with Articles 323A and 323B. The Administrative Tribunals Act followed in 1985.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-judiciary-22", "question": "Which case held that the High Courts' power of judicial review under Articles 226 and 227 is part of the basic structure, so tribunals cannot fully replace it?", "options": ["S. P. Sampath Kumar (1987)", "Indra Sawhney (1992)", "L. Chandra Kumar (1997)", "Golaknath (1967)"], "answer": 2, "explanation": "L. Chandra Kumar (1997) held that tribunal decisions can be challenged before a division bench of the High Court. This overruled the opposite view taken in S. P. Sampath Kumar (1987).", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-23", "question": "Which Article allows Parliament to set up a common High Court for two or more States?", "options": ["Article 222", "Article 231", "Article 241", "Article 214"], "answer": 1, "explanation": "Article 231, put in its present form by the 7th Amendment (1956), allows a common High Court. An example is the Gauhati High Court for Assam, Nagaland, Mizoram and Arunachal Pradesh.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-judiciary-24", "question": "Which of these is NOT a qualification for appointment as a judge of the Supreme Court?", "options": ["Ten years as an advocate of a High Court", "Five years as a judge of a High Court", "Being a distinguished jurist in the opinion of the President", "Seven years as an advocate of the Supreme Court only"], "answer": 3, "explanation": "Article 124(3) lists three routes: five years as a High Court judge, ten years as a High Court advocate, or being a distinguished jurist in the President's opinion. There is no seven-year Supreme Court advocate route.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-25", "question": "How many of these statements are correct? I. Article 32 is itself a Fundamental Right, but Article 226 is not. II. The writ jurisdiction of a High Court is wider than that of the Supreme Court. III. The right under Article 32 can be suspended only by a constitutional amendment. IV. Certiorari can be issued against a legislative body.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. The right to move the Supreme Court can be suspended during an emergency under Article 359, without any amendment. Certiorari lies against judicial and quasi-judicial bodies (and administrative authorities affecting rights), not legislatures.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-26", "question": "Match the cases with what they held: A. S. P. Gupta (1981) B. Vishaka (1997) C. Hussainara Khatoon (1979) D. Indra Sawhney (1992) — 1. Guidelines against sexual harassment at the workplace 2. Executive primacy in appointing judges 3. A cap of 50% on reservations 4. Speedy trial for undertrial prisoners", "options": ["A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3", "A-3, B-1, C-4, D-2", "A-2, B-1, C-4, D-3"], "answer": 3, "explanation": "S. P. Gupta (First Judges case) gave the executive primacy in appointments. Vishaka laid down the workplace harassment guidelines. Hussainara Khatoon, an early PIL, read speedy trial into Article 21. Indra Sawhney fixed the 50% ceiling.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-judiciary-27", "question": "Assertion (A): The writ jurisdiction of a High Court is wider than that of the Supreme Court. Reason (R): A High Court can issue writs both to enforce Fundamental Rights and “for any other purpose”.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A. Article 226 covers ordinary legal rights as well, while Article 32 is limited to Fundamental Rights.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-28", "question": "How many of these statements about removing a Supreme Court judge are correct? I. The motion must be passed in each House by a majority of its total membership and two-thirds of the members present and voting. II. The notice must be signed by 100 Lok Sabha members or 50 Rajya Sabha members. III. The inquiry committee has a Supreme Court judge, a High Court Chief Justice and a distinguished jurist. IV. No Supreme Court judge has been removed so far.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct under Article 124(4) and the Judges (Inquiry) Act, 1968. The motion against Justice V. Ramaswami (1993) failed in the Lok Sabha, so no judge has actually been removed.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-29", "question": "Which of these disputes is NOT within the Supreme Court's original jurisdiction under Article 131?", "options": ["Between two or more States", "Between the Government of India and one or more States", "Between the Centre and some States on one side and other States on the other", "An inter-State river water dispute that Parliament has excluded by law"], "answer": 3, "explanation": "Under Article 262 Parliament can exclude the jurisdiction of all courts over inter-State river water disputes, and it did so in the Inter-State River Water Disputes Act, 1956. Such disputes go to tribunals instead.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"polity-judiciary-30","question":"How many of these statements about the advisory jurisdiction are correct? I. Under Article 143(1) the Supreme Court may decline to give an opinion. II. Under Article 143(2), on pre-Constitution treaties, the Court may decline to give its opinion. III. The opinion binds the President. IV. A reference must be heard by a bench of at least seven judges.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct; the Court declined the Ayodhya reference in 1994. Under Article 143(2) the Court must give its opinion, the opinion does not bind the President, and Article 145(3) requires at least five judges, not seven.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-31", "question": "Arrange these in time order: 1. The collegium is widened to the CJI plus four senior-most judges. 2. “Consultation” is held not to mean “concurrence”, giving the executive primacy. 3. The 99th Amendment is struck down. 4. Primacy of the judiciary, with a collegium of the CJI and two senior-most judges.", "options": ["2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1", "2, 4, 1, 3"], "answer": 3, "explanation": "First Judges case 1981 (2), Second Judges case 1993 (4), Third Judges case 1998 (1), NJAC judgment 2015 (3).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-32", "question": "How many of these statements about High Courts are correct? I. A High Court judge is appointed by the President after consulting the CJI, the Governor and the Chief Justice of that High Court. II. A High Court judge resigns by writing to the Governor. III. A retired permanent High Court judge cannot plead before the High Court where they served, but can plead in the Supreme Court and other High Courts. IV. The Constitution fixes the number of judges of each High Court.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I (Article 217) and III (Article 220) are correct. A High Court judge resigns to the President. The President fixes each High Court's strength; the Constitution does not.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-33", "question": "How many of these statements about Public Interest Litigation are correct? I. PIL relaxes the traditional rule that only an affected person can approach the court. II. PIL can be filed only in the Supreme Court. III. A PIL can be filed only by a person whose own right has been violated.", "options": ["Only one", "Only two", "All three", "None"], "answer": 0, "explanation": "Only I is correct. PILs can be filed in High Courts under Article 226 as well. Any public-spirited person can file one, and courts have even treated letters as petitions.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-34", "question": "Which pair of Article and subject is NOT correctly matched?", "options": ["Article 227 — Appointment of district judges", "Article 215 — High Court as a court of record", "Article 129 — Supreme Court as a court of record", "Article 235 — High Court's control over subordinate courts"], "answer": 0, "explanation": "Article 227 gives High Courts superintendence over all courts and tribunals in their territory. District judges are appointed under Article 233.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-35", "question": "Under the collegium system set out in 1998, appointments to the High Courts are recommended (on the Supreme Court side) by the CJI and:", "options": ["the four senior-most Supreme Court judges", "the Law Minister", "the two senior-most Supreme Court judges", "the Chief Justice of that High Court alone"], "answer": 2, "explanation": "For High Court judges, the Supreme Court collegium is the CJI and the two senior-most puisne judges. The High Court's own collegium starts the proposal. The CJI plus four is the collegium for Supreme Court appointments.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-36", "question": "How many of these statements about judicial review are correct? I. The words “judicial review” do not appear in the Constitution. II. Articles 13, 32 and 226 are among its sources. III. Laws placed in the Ninth Schedule after 24 April 1973 can be tested against the basic structure. IV. Judicial review is part of the basic structure.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. I. R. Coelho (2007) used the Kesavananda date of 24 April 1973 for Ninth Schedule laws. Minerva Mills and L. Chandra Kumar treated judicial review as part of the basic structure.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-37", "question": "Assertion (A): A curative petition can be filed even after a review petition has been dismissed. Reason (R): Article 141 gives the Supreme Court power to pass any order needed for complete justice.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true (Rupa Ashok Hurra, 2002, relying on Articles 129 and 142). R is false: the “complete justice” power is in Article 142, while Article 141 makes the Court's rulings binding.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-38", "question": "How many of these statements about tribunals are correct? I. Under Article 323A, only Parliament can set up administrative tribunals. II. Under Article 323B, both Parliament and State legislatures can set up tribunals for listed matters such as taxation and land reforms. III. A tribunal under Article 323A can completely shut out the High Courts. IV. The Central Administrative Tribunal was set up under a 1985 Act.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong since L. Chandra Kumar (1997): tribunal decisions remain open to challenge before a High Court division bench.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"polity-judiciary-39","question":"Under Article 130, the Supreme Court may sit at a place other than Delhi if this is decided by:","options":["The President, on the advice of the Union Cabinet","The full court of the Supreme Court by majority","Parliament, by a law made for the purpose","The CJI, with the approval of the President"],"answer":3,"explanation":"Article 130 says the Supreme Court sits in Delhi or anywhere else the Chief Justice of India appoints with the President's approval. Parliament plays no part in this.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-40","question":"How many of these statements are correct? I. An acting Chief Justice of India is appointed by the President. II. A retired Supreme Court judge can be asked to sit by the CJI with the previous consent of the President. III. A retired High Court judge can be asked to sit in that High Court by its Chief Justice with the previous consent of the Governor. IV. Additional judges of a High Court can be appointed for up to five years.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I (Article 126) and II (Article 128) are correct. III is wrong: Article 224A needs the previous consent of the President, not the Governor. IV is wrong: additional judges are appointed for up to two years.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-41", "question": "Judges of the Supreme Court of India are appointed by the:", "options": ["Chief Justice of India", "President", "Prime Minister", "Parliament"], "answer": 1, "explanation": "Under Article 124(2) every Supreme Court judge is appointed by the President by warrant under his hand and seal; the collegium only recommends.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-judiciary-42", "question": "The Chief Justice of a High Court is appointed by the:", "options": ["Governor of the State", "Chief Minister", "Chief Justice of India", "President"], "answer": 3, "explanation": "Article 217(1) says High Court judges, including the Chief Justice, are appointed by the President after consulting the CJI and the Governor. The Governor only administers the oath.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-43", "question": "Who was the first Chief Justice of India?", "options": ["H. J. Kania", "M. Patanjali Sastri", "Mehr Chand Mahajan", "B. K. Mukherjea"], "answer": 0, "explanation": "Harilal J. Kania was the first CJI (1950–51). Patanjali Sastri, Mahajan and Mukherjea were the second, third and fourth.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id":"polity-judiciary-44","question":"District judges in a State are appointed by the:","options":["Chief Justice of the High Court acting alone","President, on the advice of the State Government","Governor, in consultation with the High Court","State Public Service Commission, after an exam"],"answer":2,"explanation":"Article 233 says appointments, postings and promotions of district judges are made by the Governor in consultation with the High Court of that State.","difficulty":"easy","source":"RRB NTPC · SSC CGL"},
  {"id": "polity-judiciary-45", "question": "Which is the oldest High Court in India, established in July 1862?", "options": ["Bombay High Court", "Madras High Court", "Allahabad High Court", "Calcutta High Court"], "answer": 3, "explanation": "The Calcutta High Court, set up under the Indian High Courts Act, 1861, began on 1 July 1862, slightly ahead of Bombay and Madras (August 1862). Allahabad came in 1866.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-46", "question": "Which writ is issued by a higher court to stop a lower court or tribunal from going beyond its jurisdiction in a case still pending before it?", "options": ["Certiorari", "Prohibition", "Mandamus", "Quo warranto"], "answer": 1, "explanation": "Prohibition is preventive and issued while proceedings are pending. Certiorari is curative, quashing an order already passed.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-judiciary-47", "question": "Which writ is used to quash an order already passed by a lower court or tribunal acting without or in excess of jurisdiction?", "options": ["Prohibition", "Habeas corpus", "Certiorari", "Mandamus"], "answer": 2, "explanation": "Certiorari (‘to be certified’) brings up the record and quashes the order once it is passed, while prohibition acts before the decision.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-judiciary-48", "question": "Which Article says that there shall be a High Court for each State?", "options": ["Article 124", "Article 214", "Article 226", "Article 231"], "answer": 1, "explanation": "Article 214 provides a High Court for each State. Article 231 lets Parliament set up a common High Court for two or more States; Article 226 is writ jurisdiction.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-49", "question": "Lok Adalats were given statutory status by the:", "options": ["Legal Services Authorities Act, 1987", "Code of Civil Procedure (Amendment) Act, 1999", "Gram Nyayalayas Act, 2008", "Arbitration and Conciliation Act, 1996"], "answer": 0, "explanation": "The Legal Services Authorities Act, 1987 (in force from 1995) gave Lok Adalats statutory backing and made their awards final and binding.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-50", "question": "Equal justice and free legal aid were added as a Directive Principle in Article 39A by the:", "options": ["24th Amendment", "42nd Amendment", "44th Amendment", "73rd Amendment"], "answer": 1, "explanation": "Article 39A was inserted by the 42nd Amendment (1976). It underpins the legal aid system under the 1987 Act.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-51", "question": "The Supreme Court's power to review any judgment or order made by it comes from:", "options": ["Article 136", "Article 137", "Article 141", "Article 143"], "answer": 1, "explanation": "Article 137 lets the Supreme Court review its own judgments, subject to law and its rules. Article 136 is special leave and Article 141 makes its law binding on other courts.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-52", "question": "An appeal lies to the Supreme Court as of right in a criminal case where a High Court has reversed an acquittal and sentenced the accused to death, under:", "options": ["Article 132", "Article 133", "Article 134", "Article 136"], "answer": 2, "explanation": "Article 134(1)(a) gives a right of appeal in such cases. Article 132 is constitutional questions and Article 133 civil appeals.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-judiciary-53","question":"Who is the Patron-in-Chief of the National Legal Services Authority (NALSA)?","options":["The President of India","The Union Law Minister","The Chief Justice of India","The Attorney General for India"],"answer":2,"explanation":"Under the 1987 Act the CJI is Patron-in-Chief of NALSA and the senior-most Supreme Court judge after him is its Executive Chairman.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-54", "question": "Gram Nyayalayas, village-level courts for quick and cheap justice, were provided for by an Act passed in:", "options": ["1987", "1996", "2008", "2013"], "answer": 2, "explanation": "The Gram Nyayalayas Act, 2008 (in force from October 2009) provides for these mobile courts at the intermediate panchayat level.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-55", "question": "The pension of a retired High Court judge is charged on the:", "options": ["Consolidated Fund of the State", "Contingency Fund of the State", "Consolidated Fund of India", "Public Account of India"], "answer": 2, "explanation": "A High Court judge's salary is charged on the Consolidated Fund of the State (Article 202), but the pension is charged on the Consolidated Fund of India (Article 112(3)(d)(iii)).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-judiciary-56","question":"For criminal contempt of the Supreme Court, a private person can move the Court only with the consent of the:","options":["Registrar General of the Supreme Court","Union Law Minister or Law Secretary","Attorney General or Solicitor General","President, on the Cabinet's advice"],"answer":2,"explanation":"Section 15 of the Contempt of Courts Act, 1971 requires the written consent of the Attorney General or Solicitor General (for a High Court, the Advocate General), unless the Court acts on its own motion.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-57", "question": "Which Article says that all civil and judicial authorities in India shall act in aid of the Supreme Court?", "options": ["Article 141", "Article 142", "Article 144", "Article 145"], "answer": 2, "explanation": "Article 144 obliges all authorities to act in aid of the Supreme Court. Article 142 is its power to do complete justice, and Article 145 its rule-making power.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-judiciary-58","question":"The Punjab and Haryana High Court at Chandigarh has jurisdiction over:","options":["Punjab and Haryana, but not Chandigarh","Punjab, Haryana and Himachal Pradesh","Punjab, Haryana and Chandigarh","Punjab, Haryana, Chandigarh and Jammu and Kashmir"],"answer":2,"explanation":"It is a common High Court for two States and one UT. Himachal Pradesh has had its own High Court since 1971.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-59", "question": "Which High Court has the largest number of States under its jurisdiction?", "options": ["Bombay High Court", "Calcutta High Court", "Gauhati High Court", "Punjab and Haryana High Court"], "answer": 2, "explanation": "The Gauhati High Court covers four States: Assam, Nagaland, Mizoram and Arunachal Pradesh. Bombay covers two States (Maharashtra, Goa) and a UT.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-judiciary-60", "question": "How many High Courts are there in India in 2026?", "options": ["21", "24", "25", "28"], "answer": 2, "explanation": "There are 25 High Courts. Some serve more than one State or UT (Gauhati, Punjab and Haryana, Bombay, and Jammu and Kashmir and Ladakh), so the number is less than the number of States.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-61", "question": "An election petition challenging the election of a member of the Lok Sabha is filed, in the first instance, in the:", "options": ["Supreme Court", "Election Commission", "High Court", "Election tribunal set up by Parliament"], "answer": 2, "explanation": "Section 80A of the Representation of the People Act, 1951 gives jurisdiction to the High Court, with appeal to the Supreme Court. Presidential and Vice-Presidential disputes go straight to the Supreme Court.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-62", "question": "When the office of Chief Justice of a High Court falls vacant, an acting Chief Justice is appointed by the:", "options": ["Governor", "Chief Justice of India", "President", "Senior-most judge of that High Court, by rotation"], "answer": 2, "explanation": "Article 223 lets the President appoint one of the judges of that High Court to perform the duties of Chief Justice.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-63", "question": "A High Court's power of superintendence over all courts and tribunals within its territory (except military tribunals) is given by:", "options": ["Article 226", "Article 227", "Article 228", "Article 235"], "answer": 1, "explanation": "Article 227 confers superintendence. Article 228 is withdrawal of cases involving constitutional questions, and Article 235 is control over subordinate courts.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-64", "question": "Under which Article may Parliament by law give the Supreme Court power to issue writs for purposes other than the enforcement of Fundamental Rights?", "options": ["Article 32(3)", "Article 138", "Article 139", "Article 226"], "answer": 2, "explanation": "Article 139 allows Parliament to widen the Supreme Court's writ power beyond Fundamental Rights. Article 32(3) lets Parliament give other courts power to issue writs within their limits.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-65", "question": "Which Article bars courts from questioning the validity of laws on the delimitation of constituencies and says an election can be challenged only by an election petition?", "options": ["Article 324", "Article 326", "Article 327", "Article 329"], "answer": 3, "explanation": "Article 329 bars courts in electoral matters. Article 324 sets up the Election Commission, 326 is adult suffrage and 327 lets Parliament legislate on elections.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-judiciary-66","question":"Under Article 139A, the Supreme Court may:","options":["Hear appeals against the orders of courts-martial and military tribunals","Withdraw cases on the same question of law from High Courts to itself","Issue advisory opinions on disputes arising from pre-Constitution treaties","Review the decisions of State Public Service Commissions on recruitment"],"answer":1,"explanation":"Article 139A, added by the 42nd Amendment, lets the Supreme Court withdraw such cases and decide them, and transfer cases between High Courts.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-67", "question": "The doctrine of ‘prospective overruling’ was first applied by the Supreme Court in:", "options": ["A. K. Gopalan case", "Golaknath case", "Kesavananda Bharati case", "Minerva Mills case"], "answer": 1, "explanation": "In Golaknath (1967) the Court held that Parliament could not amend Fundamental Rights but applied the ruling only to the future, so earlier amendments stood.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-68", "question": "Match the Union Territory with the High Court that has jurisdiction over it: A. Lakshadweep B. Andaman and Nicobar Islands C. Puducherry D. Dadra and Nagar Haveli and Daman and Diu — 1. Bombay 2. Madras 3. Calcutta 4. Kerala", "options": ["A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Lakshadweep falls under the Kerala High Court, Andaman and Nicobar under Calcutta, Puducherry under Madras, and Dadra and Nagar Haveli and Daman and Diu under Bombay.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id":"polity-judiciary-69","question":"How many of these statements about writs are correct? I. Habeas corpus can be issued against a private individual. II. Mandamus can be issued against the President or a Governor. III. Quo warranto can be sought by any person, not only an aggrieved one. IV. Prohibition can be issued against purely administrative authorities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: mandamus cannot issue against the President or a Governor (Article 361). IV is wrong: prohibition lies only against judicial and quasi-judicial bodies.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-70", "question": "Assertion (A): The salaries of Supreme Court judges cannot be reduced to their disadvantage after appointment, except during a Financial Emergency. Reason (R): Article 125 provides that the salaries of Supreme Court judges are determined by Parliament by law.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true. A rests on the proviso to Article 125(2) and on Article 360(4), which allows reduction during a Financial Emergency; R (Parliament fixes salaries) does not explain the protection.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-71", "question": "Arrange these Chief Justices of India in the order in which they held office: 1. J. S. Verma 2. Y. V. Chandrachud 3. K. G. Balakrishnan 4. P. N. Bhagwati", "options": ["2-4-1-3", "2-1-4-3", "2-4-3-1", "4-2-1-3"], "answer": 0, "explanation": "Y. V. Chandrachud (1978–85), P. N. Bhagwati (1985–86), J. S. Verma (1997–98), K. G. Balakrishnan (2007–10).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-72", "question": "Match the writ with the literal meaning of its name: A. Habeas corpus B. Mandamus C. Quo warranto D. Certiorari — 1. By what authority 2. To be certified 3. We command 4. To have the body", "options": ["A-4, B-3, C-1, D-2", "A-4, B-1, C-3, D-2", "A-4, B-3, C-2, D-1", "A-3, B-4, C-1, D-2"], "answer": 0, "explanation": "Habeas corpus means ‘to have the body’, mandamus ‘we command’, quo warranto ‘by what authority’ and certiorari ‘to be certified’ or ‘to be informed’.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-73", "question": "How many of these statements about the Supreme Court's original jurisdiction are correct? I. A dispute under Article 131 must involve a question on which the existence or extent of a legal right depends. II. Disputes about the election of the President lie in its original jurisdiction. III. Parliament can by law exclude inter-State river water disputes from its jurisdiction. IV. A private citizen can file a suit against a State under Article 131.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 131), II (Article 71) and III (Article 262(2)) are correct. IV is wrong: Article 131 covers disputes only between the Union and States or between States.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-74", "question": "Which of these is NOT a qualification or condition for appointment as a High Court judge?", "options": ["Being a citizen of India", "Having held judicial office in India for ten years", "Having been an advocate of a High Court for ten years", "Having reached the age of 35 years"], "answer": 3, "explanation": "Article 217(2) asks for citizenship and either ten years in judicial office or ten years as an advocate of a High Court. The Constitution sets no minimum age for judges, only a retirement age of 62.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-75", "question": "How many of these statements about Lok Adalats are correct? I. An award of a Lok Adalat is deemed to be a decree of a civil court. II. No appeal lies to any court against such an award. III. Court fee paid in a pending case is refunded when it is settled in a Lok Adalat. IV. Permanent Lok Adalats for public utility services were provided by a 2002 amendment to the 1987 Act.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Section 21 makes the award a decree and final; the court fee is refunded under the Court Fees Act; Chapter VI-A (2002) created Permanent Lok Adalats for public utility services.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-76", "question": "Arrange these Supreme Court judgments in time order: 1. Maneka Gandhi 2. K. S. Puttaswamy (privacy) 3. A. K. Gopalan 4. Minerva Mills", "options": ["1-3-4-2", "3-4-1-2", "3-1-4-2", "3-1-2-4"], "answer": 2, "explanation": "A. K. Gopalan (1950), Maneka Gandhi (1978), Minerva Mills (1980), K. S. Puttaswamy (2017).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-77", "question": "How many of these statements about contempt of court are correct? I. Articles 129 and 215 make the Supreme Court and High Courts courts of record with power to punish contempt of themselves. II. The Contempt of Courts Act, 1971 defines only criminal contempt. III. The Act allows simple imprisonment of up to six months, or a fine of up to ₹2,000, or both. IV. Truth can never be pleaded as a defence in contempt proceedings.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. II is wrong: the Act defines both civil and criminal contempt. IV is wrong: a 2006 amendment allows truth as a defence if it is in the public interest and the plea is bona fide.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-78", "question": "Assertion (A): The Supreme Court is bound by its own earlier decisions. Reason (R): Under Article 141, the law declared by the Supreme Court is binding on all courts within India.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: the Supreme Court can depart from its earlier rulings (Bengal Immunity, 1955); a smaller bench is bound by a larger one, but the Court as a whole is not bound. R is true, but ‘all courts’ means courts other than the Supreme Court itself.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-79", "question": "Match the Article with its subject: A. Article 214 B. Article 217 C. Article 222 D. Article 224 — 1. Transfer of a judge from one High Court to another 2. Additional and acting judges 3. Appointment and conditions of office of a High Court judge 4. High Courts for States", "options": ["A-4, B-3, C-2, D-1", "A-4, B-1, C-3, D-2", "A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2"], "answer": 3, "explanation": "Article 214 provides High Courts for States, 217 governs appointment, 222 transfers, and 224 additional and acting judges.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-80", "question": "How many of these statements about the National Judicial Appointments Commission are correct? I. The 99th Amendment inserted Article 124A to create it. II. It was to have six members: the CJI, two senior-most Supreme Court judges, the Union Law Minister and two eminent persons. III. The Supreme Court struck it down in 2015 by a 4:1 majority. IV. Justice J. Chelameswar was the dissenting judge.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. In the Fourth Judges case (2015) the majority held that the NJAC compromised judicial independence; Justice Chelameswar upheld it.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-judiciary-81","question":"How many of these statements about Article 145 are correct? I. A substantial question of law on the interpretation of the Constitution must be heard by at least five judges. II. A reference under Article 143 must also be heard by at least five judges. III. Every judgment must be delivered in open court. IV. A judge who does not agree with the majority may deliver a dissenting judgment or opinion.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: Article 145(3) needs at least five judges for a substantial question on interpretation and for an Article 143 reference, Article 145(4) requires judgment in open court, and Article 145(5) allows dissent.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-82", "question": "How many of these statements are correct? I. M. Fathima Beevi was the first woman judge of the Supreme Court. II. Leila Seth was the first woman to become Chief Justice of a High Court. III. Indira Banerjee was the first woman appointed to the Supreme Court directly from the Bar. IV. Anna Chandy was the first woman judge of the Supreme Court.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I (1989) and II (Himachal Pradesh, 1991) are correct. III is wrong: Indu Malhotra (2018) was the first woman elevated directly from the Bar. IV is wrong: Anna Chandy was the first woman High Court judge (Kerala, 1959).", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-83", "question": "Assertion (A): Parliament can raise the number of Supreme Court judges by an ordinary law. Reason (R): Article 124(1) leaves the number of judges, other than the Chief Justice, to be prescribed by Parliament by law.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: Parliament has raised the strength several times through the Supreme Court (Number of Judges) Act, 1956, without a constitutional amendment.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-judiciary-84", "question": "Which pair of State and principal seat of its High Court is NOT correctly matched?", "options": ["Madhya Pradesh – Jabalpur", "Rajasthan – Jaipur", "Chhattisgarh – Bilaspur", "Odisha – Cuttack"], "answer": 1, "explanation": "The Rajasthan High Court's principal seat is at Jodhpur; Jaipur has a bench. The other three are principal seats.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-judiciary-85", "question": "How many of these statements about the 42nd and 43rd Amendments are correct? I. The 42nd Amendment inserted Article 32A, barring the Supreme Court from considering the validity of State laws in Article 32 proceedings. II. It inserted Article 131A, giving the Supreme Court exclusive jurisdiction over the validity of Central laws. III. Article 144A required at least seven judges and a two-thirds majority to strike down a law. IV. The 43rd Amendment (1977) omitted these provisions.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The 42nd Amendment curtailed judicial review in 1976, and the 43rd Amendment restored the courts' earlier powers by omitting Articles 32A, 131A, 144A, 226A and 228A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-judiciary-86","question":"Before entering office, a judge of the Supreme Court makes the oath or affirmation before:","options":["The Chief Justice of India, in open court","The President, or a person appointed by him","The Vice-President, as Chairman of the Rajya Sabha","The Speaker, in a joint sitting of Parliament"],"answer":1,"explanation":"Article 124(6) requires the oath before the President or a person he appoints; in practice the CJI administers it to other judges. The form is in the Third Schedule.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"polity-judiciary-87","question":"Which court is at the head of the judicial system within a district?","options":["Court of the Senior Civil Judge","Court of the Chief Judicial Magistrate","Court of the District and Sessions Judge","Court of the District Collector and Magistrate"],"answer":2,"explanation":"The District Judge (called Sessions Judge on the criminal side) heads the district judiciary. Munsiffs and magistrates are subordinate to him; the Collector's court is a revenue court.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id": "polity-judiciary-88", "question": "Which institution is called the guardian of the Constitution and protector of Fundamental Rights in India?", "options": ["Parliament", "The President", "The Election Commission", "The Supreme Court"], "answer": 3, "explanation": "The Supreme Court interprets the Constitution and enforces Fundamental Rights through Article 32, which makes it the guardian of the Constitution.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "polity-judiciary-89", "question": "The National Green Tribunal was set up under an Act passed in:", "options": ["2005", "2010", "2013", "2002"], "answer": 1, "explanation": "The National Green Tribunal Act, 2010 created a specialised body for environmental cases, drawing on Article 21 and Article 48A. Its principal bench is in New Delhi.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-judiciary-90", "question": "Who became the 53rd Chief Justice of India in November 2025?", "options": ["Sanjiv Khanna", "B. R. Gavai", "Surya Kant", "D. Y. Chandrachud"], "answer": 2, "explanation": "Justice Surya Kant succeeded B. R. Gavai (the 52nd CJI) in November 2025. Sanjiv Khanna was the 51st and D. Y. Chandrachud the 50th.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id":"polity-judiciary-91","question":"Under Article 124(7), a person who has held office as a judge of the Supreme Court may NOT plead or act:","options":["In any court or authority within India","Only in the Supreme Court, for five years","Only in the High Court of his home State","Only before tribunals and commissions"],"answer":0,"explanation":"The bar on retired Supreme Court judges is total. A retired High Court judge is barred only in that High Court and courts below it, and may practise in the Supreme Court and other High Courts (Article 220).","difficulty":"moderate","source":"SSC CGL · State PSCs"},
  {"id": "polity-judiciary-92", "question": "Family Courts for speedy settlement of matrimonial and family disputes were provided for by an Act passed in:", "options": ["1976", "1987", "1993", "1984"], "answer": 3, "explanation": "The Family Courts Act was passed in 1984. The Legal Services Authorities Act, which gave Lok Adalats statutory status, came in 1987.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"polity-judiciary-93","question":"Who was the first Chief Justice of India from a Dalit community?","options":["K. G. Balakrishnan","B. R. Gavai","M. Hidayatullah","Mirza Hameedullah Beg"],"answer":0,"explanation":"K. G. Balakrishnan was CJI from 2007 to 2010. B. R. Gavai, CJI in 2025, was the second CJI from a Scheduled Caste background.","difficulty":"moderate","source":"SSC CGL · State PSCs"},
  {"id": "polity-judiciary-94", "question": "In 2020 the Supreme Court held advocate Prashant Bhushan guilty of contempt for his tweets. What punishment did it impose?", "options": ["Six months' simple imprisonment", "A fine of Re 1", "A fine of Rs 2,000", "Suspension of his licence to practise"], "answer": 1, "explanation": "The Court imposed a token fine of Re 1, with three months' jail and a three-year practice bar if unpaid. The 1971 Act allows up to six months or Rs 2,000.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id":"polity-judiciary-95","question":"Under Article 146, the officers and servants of the Supreme Court are appointed by:","options":["The President, on the Cabinet's advice","The Union Public Service Commission","The Department of Justice in the Law Ministry","The CJI, or a judge or officer he directs"],"answer":3,"explanation":"Article 146 gives the CJI control over the Court's staff, and its administrative expenses are charged on the Consolidated Fund of India. Article 229 gives High Court Chief Justices a similar power.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-96", "question": "Under Article 145, the Supreme Court makes rules for regulating its practice and procedure, subject to any law made by Parliament, with the approval of the:", "options": ["Union Law Minister", "President", "Parliament", "Full court of all judges, without outside approval"], "answer": 1, "explanation": "Article 145(1) requires the President's approval for the Supreme Court Rules. Article 145(3) separately fixes a minimum of five judges for constitutional questions.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-judiciary-97","question":"Under Article 234, appointments of persons other than district judges to the judicial service of a State are made by the Governor in accordance with rules made after consulting:","options":["The State Public Service Commission and High Court","The Chief Minister and the State's Advocate General","The Union Public Service Commission and the CJI","The State Legislature and the Law Department"],"answer":0,"explanation":"Article 234 involves both the State PSC and the High Court. District judges are appointed under Article 233 by the Governor in consultation with the High Court.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id": "polity-judiciary-98", "question": "In April 1973, a day after the Kesavananda Bharati judgment, which judge was appointed Chief Justice of India superseding three senior judges?", "options": ["M. H. Beg", "Y. V. Chandrachud", "A. N. Ray", "P. N. Bhagwati"], "answer": 2, "explanation": "A. N. Ray was appointed over Justices Shelat, Hegde and Grover, who resigned in protest. M. H. Beg's appointment in 1977 superseded H. R. Khanna.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-judiciary-99","question":"Under Article 312, Parliament may create an All-India Judicial Service. Which posts does Article 312(3) expressly exclude from it?","options":["Posts of district judge and additional district judge","Posts in the registries of the Supreme Court","Posts of judges of the High Courts","Any post below that of a district judge"],"answer":3,"explanation":"Article 312(3) says the service shall not include any post inferior to a district judge. It needs a Rajya Sabha resolution under Article 312(1); no such service has been created yet.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-100","question":"In Daryao v. State of U.P. (1961), the Supreme Court held that:","options":["Res judicata bars an Article 32 petition on a matter a High Court decided on merits","High Courts cannot issue writs to enforce Fundamental Rights while Article 32 is available","Article 32 can be suspended by an ordinary law of Parliament during peace","Public interest petitions need no affected party and are exempt from res judicata"],"answer":0,"explanation":"Daryao applied res judicata to writ petitions: once a High Court decides a matter on merits, the same claim cannot be reopened through Article 32; the remedy is an appeal.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-101", "question": "The first reference made by the President to the Supreme Court under Article 143 concerned:", "options": ["The Kerala Education Bill", "The Delhi Laws Act", "The Berubari Union", "The Special Courts Bill"], "answer": 1, "explanation": "In re Delhi Laws Act (1951), on delegated legislation, was the first advisory reference. The Kerala Education Bill (1958), Berubari (1960) and Special Courts Bill (1978) references came later.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-102", "question": "In 2013 three new High Courts were set up for States that had earlier been under the Gauhati High Court. Which of these was NOT one of them?", "options": ["Manipur", "Meghalaya", "Tripura", "Mizoram"], "answer": 3, "explanation": "Manipur, Meghalaya and Tripura got their own High Courts in March 2013. Mizoram, along with Assam, Nagaland and Arunachal Pradesh, remains under the Gauhati High Court.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-judiciary-103", "question": "Under Section 22 of the National Green Tribunal Act, 2010, an appeal against an order of the Tribunal lies to the:", "options": ["High Court of the State concerned", "Union Ministry of Environment", "Supreme Court", "Central Pollution Control Board"], "answer": 2, "explanation": "Appeals from the NGT go directly to the Supreme Court, ordinarily within 90 days. This is why environment cases decided by the NGT skip the High Courts on appeal.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-judiciary-104","question":"Under Article 134A, inserted by the 44th Amendment, the certificate of fitness for an appeal to the Supreme Court is granted by:","options":["The Supreme Court itself, on special leave","The President, on the Law Ministry's advice","The Attorney General for India","The High Court that passed the judgment"],"answer":3,"explanation":"Article 134A lets the High Court grant the certificate needed under Articles 132, 133 and 134(1)(c), on its own or on an oral application right after the judgment.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-judiciary-105", "question": "Match the State with the principal seat of its High Court: A. Kerala B. Uttarakhand C. Himachal Pradesh D. Gujarat — 1. Shimla 2. Ahmedabad 3. Nainital 4. Ernakulam (Kochi)", "options": ["A-4, B-1, C-3, D-2", "A-4, B-3, C-1, D-2", "A-2, B-3, C-1, D-4", "A-4, B-3, C-2, D-1"], "answer": 1, "explanation": "The Kerala High Court sits at Ernakulam, not Thiruvananthapuram; Uttarakhand's at Nainital, not Dehradun; Himachal's at Shimla; Gujarat's at Ahmedabad, not Gandhinagar.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-judiciary-106", "question": "Article 233A, which validated the appointments of certain district judges after the Supreme Court found them irregular in Chandra Mohan v. State of U.P., was inserted by the:", "options": ["7th Amendment, 1956", "15th Amendment, 1963", "20th Amendment, 1966", "42nd Amendment, 1976"], "answer": 2, "explanation": "The 20th Amendment (1966) added Article 233A to save judgments and appointments affected by Chandra Mohan, which held that the Governor must consult the High Court.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-107", "question": "Consider the following statements: 1. In 2011 the Rajya Sabha passed a motion for the removal of Justice Soumitra Sen of the Calcutta High Court. 2. He was removed after the Lok Sabha also passed the motion. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Justice Sen resigned before the Lok Sabha took up the motion, so it lapsed; no judge has ever been removed under Article 124(4) or 218.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-108", "question": "Consider the following statements: 1. Y. V. Chandrachud had the longest tenure of any Chief Justice of India. 2. Kamal Narain Singh had the shortest tenure as Chief Justice of India. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Chandrachud served from 1978 to 1985, over seven years; Kamal Narain Singh served for only about 17 days in 1991.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "polity-judiciary-109", "question": "Arrange these advisory references under Article 143 in chronological order: 1. Kerala Education Bill 2. Berubari Union 3. Special Courts Bill 4. Delhi Laws Act", "options": ["4, 2, 1, 3", "1, 4, 2, 3", "4, 1, 3, 2", "4, 1, 2, 3"], "answer": 3, "explanation": "Delhi Laws Act (1951), Kerala Education Bill (1958), Berubari Union (1960) and Special Courts Bill (1978).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-110", "question": "Assertion (A): A High Court can issue a writ to an authority located outside its territory if the cause of action arises wholly or partly within its territory. Reason (R): Clause (2) of Article 226, added by the 15th Amendment, 1963, provides for this.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Before 1963 a writ could issue only to authorities located within the court's territory, which forced cases against the Centre to go to the Punjab High Court.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-111", "question": "Consider the following statements: 1. Officers and servants of a High Court are appointed by the Chief Justice of that High Court. 2. The administrative expenses of a High Court are charged on the Consolidated Fund of India. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct (Article 229). A High Court's administrative expenses are charged on the Consolidated Fund of the State; it is the Supreme Court's expenses that are charged on the Consolidated Fund of India.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-112", "question": "Arrange these High Courts in the order in which they were established: 1. Andhra Pradesh High Court at Amaravati 2. Allahabad High Court 3. Tripura High Court 4. Calcutta High Court", "options": ["4, 2, 3, 1", "2, 4, 3, 1", "4, 3, 2, 1", "4, 2, 1, 3"], "answer": 0, "explanation": "Calcutta (1862), Allahabad (1866), Tripura (2013) and the separate Andhra Pradesh High Court (1 January 2019), which made the total 25.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-judiciary-113", "question": "Consider the following statements: 1. M. H. Beg was appointed Chief Justice of India in 1977, superseding H. R. Khanna. 2. Khanna had written the lone dissent in ADM Jabalpur. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Khanna resigned after being superseded; his ADM Jabalpur dissent was vindicated when the judgment was overruled in Puttaswamy (2017).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-114", "question": "Match the tribunal with the law that created it: A. National Green Tribunal B. Armed Forces Tribunal C. Central Administrative Tribunal D. National Company Law Tribunal — 1. Administrative Tribunals Act, 1985 2. Companies Act, 2013 3. National Green Tribunal Act, 2010 4. Armed Forces Tribunal Act, 2007", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "NGT: 2010 Act; AFT: 2007 Act; CAT: Administrative Tribunals Act, 1985 under Article 323A; NCLT: Companies Act, 2013.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-judiciary-115", "question": "Which of these is NOT a ground on which a High Court judge's office becomes vacant?", "options": ["Resignation addressed to the President", "Removal by the President on an address by both Houses of Parliament", "Appointment as a judge of the Supreme Court", "A resolution of the State Legislative Assembly"], "answer": 3, "explanation": "Under Article 217(1), a High Court judge's office ends by resignation to the President, removal through Parliament, appointment to the Supreme Court or transfer to another High Court. A State Legislature has no role in removal.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-116","question":"Once a motion to remove a Supreme Court judge is admitted, the Judges (Inquiry) Act, 1968 provides for a three-member inquiry committee. Who are its members?","options":["The Chief Justice of India, the Attorney General and the Union Law Minister","An SC judge or the CJI, a High Court Chief Justice and a distinguished jurist","Three senior judges of the Supreme Court nominated by the collegium","The Speaker, the Chairman of the Rajya Sabha and a retired Supreme Court judge"],"answer":1,"explanation":"Section 3(2) of the Act prescribes these three. The Speaker or Chairman only admits the motion and constitutes the committee; Parliament votes later only if the judge is found guilty.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-117","question":"Consider the following statements about ad hoc judges of the Supreme Court under Article 127: 1. Only a retired Supreme Court judge can be appointed. 2. The Chief Justice of India must consult the Chief Justice of the High Court concerned. 3. While so sitting, the ad hoc judge has only the jurisdiction and powers of a High Court judge. How many of the above statements are correct?","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only 2 is correct. Article 127 appoints a High Court judge duly qualified to be a Supreme Court judge (retired SC judges sit under Article 128), and while sitting he has all the jurisdiction, powers and privileges of a Supreme Court judge.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-118","question":"Consider the following statements about Article 128: 1. The Chief Justice of India may, with the President's previous consent, request a retired judge to sit and act as a Supreme Court judge. 2. A retired High Court judge who is duly qualified for appointment to the Supreme Court may also be requested. 3. A retired judge so requested cannot decline. Which of the above are correct?","options":["1 and 2 only","1 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Article 128 covers retired Supreme Court judges and qualified retired High Court judges, but expressly requires the person's own consent, so 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-119","question":"Consider the following statements: 1. The President may appoint additional judges of a High Court for up to two years to deal with a temporary increase in business or arrears. 2. The Chief Justice of a High Court may, with the President's previous consent, request a retired High Court judge to sit and act as a judge. 3. An additional judge may continue beyond 62 if his two-year term has not ended. Which of the above are correct?","options":["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Articles 224 and 224A support 1 and 2. Article 224(3) bars any additional or acting judge from holding office beyond 62.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-120","question":"Consider the following statements: 1. A question about the age of a High Court judge is decided by the President after consulting the Chief Justice of India, and the decision is final. 2. The age of a Supreme Court judge is determined by such authority and in such manner as Parliament may by law provide. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Article 217(3) covers High Court judges. Article 124(2A), added by the 15th Amendment (1963), leaves the Supreme Court case to a law of Parliament.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-121","question":"After retiring as a permanent judge of a High Court, a person wants to resume legal practice. Under Article 220, he may plead:","options":["before the Supreme Court and other High Courts, but not his own","in any court in India, including the High Court where he served","only before tribunals and arbitral bodies, not before any court","only before the Supreme Court, and in no High Court at all"],"answer":0,"explanation":"Article 220 bars him only from his own High Court and its subordinate courts. A retired Supreme Court judge, by contrast, cannot plead in any court in India (Article 124(7)).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-122","question":"Before entering office, a judge of a High Court makes the oath or affirmation before:","options":["the Chief Justice of that High Court, in open court","the Governor of the State, or a person he appoints","the President of India, who appoints him","the Chief Justice of India or a judge he nominates"],"answer":1,"explanation":"Article 219 requires the oath before the Governor or someone he appoints, though the President appoints High Court judges. Supreme Court judges take their oath before the President.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-123","question":"In Union of India v. Sankalchand Sheth (1977), on the transfer of High Court judges under Article 222, the Supreme Court held that:","options":["a judge can be transferred only with his own consent, since transfer changes his service conditions","the President may transfer a judge without consulting the CJI if public interest requires","transfer is a form of punishment and so needs a prior inquiry into the judge's conduct","his consent is not needed, but there must be full and effective consultation with the CJI"],"answer":3,"explanation":"The Court held that consent is not required, but the transfer must serve the public interest and follow real consultation with the CJI. It is not a punitive measure.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-124","question":"A High Court grants an interim order under Article 226 without notice to the other party, which then applies to have it vacated. Under Article 226(3):","options":["the Court must decide the application within two weeks, or the interim order stands vacated","the interim order continues until the Court decides the application, however long that takes","the interim order lapses automatically one month after it was granted","the other party's only remedy is a special leave petition to the Supreme Court"],"answer":0,"explanation":"Clause (3), in its 44th Amendment form, sets a two-week deadline (or the next working day) after which the ex parte interim order stands vacated.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-125","question":"A case pending in a subordinate court raises a substantial question of law on the interpretation of the Constitution, and deciding it is necessary to dispose of the case. Under Article 228, the High Court:","options":["must refer the question to the Supreme Court under Article 143 for its opinion","may decide the question only if both parties consent to the withdrawal","shall withdraw the case and decide it, or decide the question and return it","has no power to intervene until the subordinate court gives judgment"],"answer":2,"explanation":"Article 228 obliges the High Court to withdraw the case; it may then decide the whole case or only the constitutional question. Article 143 is a reference by the President, not by courts.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-126","question":"A practising lawyer who is not in government service wants to be appointed directly as a district judge. Under Article 233(2), he must:","options":["have been an advocate for at least ten years and be recommended by the State PSC","have practised for at least seven years and be recommended by the High Court","have held judicial office for at least five years and pass a State PSC exam","be recommended by the Chief Justice of India after an interview by the collegium"],"answer":1,"explanation":"Article 233(2) requires seven years at the bar and the High Court's recommendation; the Governor then appoints. Ten years is the requirement for a High Court judge.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-127","question":"Control over district courts and subordinate courts, including the posting, promotion and leave of judicial officers below the rank of district judge, is vested by Article 235 in the:","options":["Governor","State Public Service Commission","State Law Department","High Court"],"answer":3,"explanation":"Article 235 gives the High Court control over the subordinate judiciary, which protects its independence from the State executive.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-128","question":"Which statement about the writ of quo warranto is correct?","options":["Even a person who is not aggrieved may seek it against a usurper of a public office","It can be issued against a person holding a ministerial office or a private office","Only a person who claims the office for himself, as the rightful holder, can seek it","It is used to compel a public official to perform a duty imposed on him by statute"],"answer":0,"explanation":"Quo warranto tests title to a substantive public office and does not need a personally aggrieved petitioner. It does not lie for ministerial or private offices; compelling a duty is mandamus.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-129","question":"Against which of the following can a writ of mandamus be issued?","options":["The Governor of a State, for acts done in his personal capacity","A private individual, to enforce a contract","A public authority that refuses to perform a statutory duty owed to the petitioner","An authority, to make it exercise a purely discretionary power in a particular way"],"answer":2,"explanation":"Mandamus enforces a public legal duty. It does not lie against the President or Governor personally (Article 361), against private persons, to enforce contracts, or to dictate discretion.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-130","question":"Consider the following statements about writs: 1. Prohibition can be issued only while proceedings are pending before the lower court or tribunal. 2. Certiorari is not available against legislative bodies or private individuals. 3. Prohibition can be issued against purely administrative authorities. Which of the above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Prohibition is preventive and lies only against judicial or quasi-judicial bodies, so 3 is wrong. Certiorari has been extended to administrative authorities affecting rights, but not to legislatures or private persons.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-131","question":"In which of these situations will a court NOT issue a writ of habeas corpus?","options":["A person is held by a private individual against his will","A person is held by the police without being produced before a magistrate","A person is held under a preventive detention law without a valid order","A person is jailed for contempt of a court or of a legislature"],"answer":3,"explanation":"Habeas corpus lies even against private detention, but not where the detention is lawful, such as committal for contempt of court or legislature, or detention by a competent court.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-132","question":"In ADM Jabalpur v. Shivkant Shukla (1976), the majority of the Supreme Court held that:","options":["no detenu could seek habeas corpus, even alleging illegality or mala fides","detenus could still challenge a detention shown to be mala fide or ultra vires the Act","Article 21 itself stood repealed for the duration of the Emergency proclamation","habeas corpus remained available, but only in the Supreme Court under Article 32"],"answer":0,"explanation":"The 4:1 majority closed the courts to detenus; Justice H. R. Khanna dissented. The nine-judge bench in Puttaswamy (2017) declared the majority view overruled.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-133","question":"Match the doctrine with the case associated with it: A. Doctrine of eclipse B. Doctrine of severability C. No waiver of Fundamental Rights D. Prospective overruling — 1. Basheshar Nath (1959) 2. Golaknath (1967) 3. Bhikaji Narain Dhakras (1955) 4. R. M. D. Chamarbaugwalla (1957)","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":2,"explanation":"Bhikaji Narain held a pre-Constitution law is eclipsed, not dead; RMDC applied severability; Basheshar Nath held Fundamental Rights cannot be waived; Golaknath introduced prospective overruling.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-134","question":"Under Article 138, how can the jurisdiction of the Supreme Court be enlarged?","options":["Only by a constitutional amendment passed under Article 368 by special majority","By Parliament by law (Union List), or by Union-State agreement if Parliament allows","By the President by order, after consulting the CJI and the Attorney General","By the Supreme Court itself, through rules of procedure framed under Article 145"],"answer":1,"explanation":"Article 138(1) lets Parliament enlarge jurisdiction on Union List matters; Article 138(2) allows more by special agreement between the Union and a State, if Parliament provides for it by law.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-135","question":"Consider the following statements: 1. Parliament may discuss the conduct of a High Court judge in the discharge of his duties when a motion for his removal is before it. 2. A State legislature may discuss the conduct of a judge of its High Court when an address for his removal is under consideration. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Article 121 allows discussion only on a removal motion. Article 211 bars State legislatures from discussing judges' conduct at all, since they have no role in removing judges.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-136","question":"Which Article allows Parliament by law to empower any other court to exercise, within its local limits, the Supreme Court's power to issue writs for enforcing Fundamental Rights?","options":["Article 139","Article 226","Article 138(2)","Article 32(3)"],"answer":3,"explanation":"Article 32(3) lets Parliament confer the Supreme Court's writ powers on other courts. High Courts already have their own writ power under Article 226, Article 138(2) enlarges the Supreme Court's own jurisdiction by agreement, and Article 139 deals with writs for other purposes.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-137","question":"Consider the following statements about the Contempt of Courts Act, 1971: 1. The maximum punishment is simple imprisonment up to six months, or a fine up to ₹2,000, or both. 2. Since a 2006 amendment, truth can be a valid defence if it is in the public interest and the defence is bona fide. 3. An apology, once tendered, must be accepted and the contemnor discharged. Which of the above are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Section 12 sets the punishment and allows discharge on an apology only if the court is satisfied it is bona fide. Section 13 was amended in 2006 to allow justification by truth.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-138","question":"Assertion (A): The Supreme Court may treat a letter written to it as a writ petition under Article 32. Reason (R): Article 32(1) guarantees the right to move the Court by ‘appropriate proceedings’ and prescribes no particular form for them.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In Bandhua Mukti Morcha (1984) and earlier cases, the Court read ‘appropriate proceedings’ broadly, so a letter could suffice. This is the basis of its epistolary jurisdiction.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-139","question":"After L. Chandra Kumar v. Union of India (1997), an order of the Central Administrative Tribunal is challenged first before:","options":["the Supreme Court directly, by special leave under Article 136","a larger bench of the CAT presided over by its Chairman","a Division Bench of the High Court concerned","the Union Government, on a revision petition under Article 323A"],"answer":2,"explanation":"The Court held tribunals cannot oust the High Courts' power under Articles 226 and 227, so their decisions go first to a Division Bench of the High Court.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-140","question":"Under Article 323B, a State legislature can set up a tribunal for which of these matters?","options":["Recruitment and service conditions of Union Government employees","Disputes about the election of the President","Inter-State river water disputes","Rent and tenancy rights"],"answer":3,"explanation":"Article 323B lists matters such as taxation, land reforms, rent and tenancy, and industrial disputes. Public service tribunals under Article 323A can be set up only by Parliament.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-141","question":"In 1993 the President referred a question on the Ayodhya dispute to the Supreme Court under Article 143(1). What did the Court do in M. Ismail Faruqui (1994)?","options":["It answered the reference in favour of the Union Government","It respectfully declined to answer the reference","It held the reference was barred by Article 131","It transferred the question to the Allahabad High Court under Article 139A"],"answer":1,"explanation":"Article 143(1) says the Court ‘may’ report its opinion, so it can decline, as it did here. Only references under Article 143(2) must be answered.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-142","question":"In Delhi Judicial Service Association v. State of Gujarat (1991), arising from the assault on a Chief Judicial Magistrate at Nadiad, the Supreme Court held that under Article 129 it can punish contempt:","options":["only of itself, never of any other court","of itself and of the High Courts, but not of subordinate courts","of itself and also of subordinate courts in India","only when the High Court concerned refers the matter to it"],"answer":2,"explanation":"The Court held that its power as a court of record under Article 129 extends to protecting subordinate courts from contempt, since it heads the whole judicial system.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-143","question":"Calling the Supreme Court a ‘court of record’ means, among other things, that:","options":["its records are conclusive evidence, and it can punish for contempt of itself","it must keep a written record of every case filed in any court anywhere in India","it can hear only those cases in which a full written record of the trial exists","its records and judgments can be amended by Parliament through ordinary law"],"answer":0,"explanation":"Under Article 129, records of a court of record carry evidentiary value and cannot be questioned when produced in any court; the status also carries the power to punish for contempt.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-144","question":"In Mohd. Arif v. Registrar, Supreme Court of India (2014), the Court held that review petitions in cases where the death sentence has been imposed:","options":["must be decided by circulation in chambers like other review petitions","must get an oral hearing in open court before at least three judges","cannot be filed once a curative petition has been dismissed","must be heard by a Constitution Bench of five judges"],"answer":1,"explanation":"Because the right to life is at stake, the Court required a limited oral hearing in open court before a bench of three or more judges. Other review petitions are usually decided by circulation.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-145","question":"In Zee Telefilms v. Union of India (2005), the Supreme Court held that the BCCI:","options":["is ‘State’ under Article 12, so a writ petition under Article 32 lies against it","is a private society, so no writ of any kind can ever lie against it","is ‘State’ because the Government controls its finances and its administration","is not ‘State’, but a High Court writ may lie for its public functions"],"answer":3,"explanation":"By 3:2 the Court held the BCCI is not State, so Article 32 was unavailable. Since it discharges public functions, a High Court can still reach it under Article 226.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-146","question":"Even before PIL relaxed the rule of locus standi, which two writs could be sought by a person who was not personally aggrieved?","options":["Habeas corpus and quo warranto","Prohibition and quo warranto","Habeas corpus and certiorari","Mandamus and certiorari"],"answer":0,"explanation":"Habeas corpus can be sought by anyone on the detenu's behalf, and quo warranto by anyone questioning a usurper's title. The other writs traditionally needed an aggrieved petitioner.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-147","question":"The number of judges of a High Court is fixed by:","options":["Parliament by law","the Governor of the State, on the High Court's advice","the President","the Chief Justice of India"],"answer":2,"explanation":"Article 216 lets the President appoint as many judges as he deems necessary. For the Supreme Court the number is fixed by Parliament by law (Article 124(1)), the usual trap.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-148","question":"Consider the following statements: 1. The Federal Court of India was set up in 1937 under the Government of India Act, 1935. 2. Appeals from Indian courts to the Privy Council were abolished by a law passed in 1949. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"The Federal Court began in 1937 and the Abolition of Privy Council Jurisdiction Act came in 1949. The Supreme Court took over both roles from January 1950.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-149","question":"Consider the following statements about Article 124(2): 1. When appointing a Supreme Court judge other than the Chief Justice, the President must always consult the Chief Justice of India. 2. The Article expressly provides that the senior-most judge shall be appointed Chief Justice of India. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The proviso makes consulting the CJI compulsory. Appointing the senior-most judge as CJI is only a convention, broken in 1973 and 1977, not a text in the Constitution.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-150","question":"Who was the first Supreme Court judge against whom a removal motion was taken up and put to vote in Parliament?","options":["Justice Dipak Misra","Justice V. Ramaswami","Justice Soumitra Sen","Justice P. D. Dinakaran"],"answer":1,"explanation":"The 1993 motion against Justice V. Ramaswami failed in the Lok Sabha for want of the special majority, as the ruling party abstained. Soumitra Sen and Dinakaran were High Court judges.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-151","question":"A three-judge bench of the Supreme Court disagrees with an earlier judgment of another three-judge bench. What should it do?","options":["Overrule the earlier judgment, since benches of equal strength have equal authority","Follow its own view and leave the conflict for the High Courts to resolve","Seek the President's opinion under Article 143","Refer the matter to a larger bench"],"answer":3,"explanation":"A bench cannot overrule a coordinate bench; it must refer the question to a larger bench (Central Board of Dawoodi Bohra Community, 2005). A larger bench's ruling binds smaller ones.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-152","question":"A judgment is said to be ‘per incuriam’ when it is:","options":["delivered by a bench that lacked the required minimum number of judges","made in ignorance of a binding law or precedent, so it does not bind","later overruled by a larger bench, but only with prospective effect","given by a judge who had a personal or pecuniary interest in the case"],"answer":1,"explanation":"A per incuriam decision overlooked a binding law or precedent, so it loses its binding force under Article 141. Bias by a judge makes a decision void on another ground.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-153","question":"In Mahesh Chandra Gupta v. Union of India (2009), on challenges to the appointment of High Court judges, the Supreme Court held that:","options":["neither eligibility nor suitability can ever be examined by a court","both eligibility and suitability are fully open to judicial review","eligibility is justiciable as an objective fact, but suitability is not","only the President's satisfaction can be questioned, on the ground of mala fides"],"answer":2,"explanation":"The Court drew this line: whether a person meets Article 217 qualifications can be tested in court; whether he is fit for the post is left to the consultative process.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-154","question":"A High Court judge is transferred to another High Court under Article 222. Under clause (2), in addition to salary he is entitled to:","options":["a transfer grant fixed by the Chief Justice of India","no extra amount, since salaries are uniform across High Courts","an allowance fixed by the Governor of the receiving State","a compensatory allowance determined by Parliament by law"],"answer":3,"explanation":"Article 222(2) provides for a compensatory allowance as Parliament determines by law (and, until then, as the President fixes by order).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-155","question":"A judge of a High Court who wishes to resign does so by writing addressed to the:","options":["President","Governor of the State","Chief Justice of the High Court","Chief Justice of India"],"answer":0,"explanation":"Under Article 217(1)(a), a High Court judge resigns to the President, who appoints him. The oath, by contrast, is taken before the Governor.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-156","question":"The Directive in Article 50 to separate the judiciary from the executive was given practical effect in criminal courts mainly by:","options":["the 42nd Amendment, which made Article 50 justiciable","the CrPC, 1973, which split judicial from executive magistrates","the Legal Services Authorities Act, 1987, which set up Lok Adalats","the Gram Nyayalayas Act, 2008, which set up village courts"],"answer":1,"explanation":"The 1973 Code placed judicial magistrates under the High Court and confined executive magistrates to preventive and administrative functions.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-157","question":"Consider the following statements: 1. A High Court can issue writs under Article 226 to enforce ordinary legal rights as well as Fundamental Rights. 2. A petition under Article 32 lies only for the enforcement of Fundamental Rights. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Article 226 reaches ‘any other purpose’, so it is wider. Article 32 is limited to Part III rights, though it is itself a Fundamental Right.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-158","question":"Consider the following statements: 1. The word ‘collegium’ does not appear anywhere in the Constitution. 2. In the Second Judges case (1993), ‘consultation’ with the Chief Justice of India was read to mean ‘concurrence’. 3. In the First Judges case (1981), the Court gave primacy to the opinion of the Chief Justice of India. Which of the above are correct?","options":["1 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"S. P. Gupta (1981) gave the executive the final say. The Second Judges case reversed this, and the collegium grew out of judicial interpretation, not the text.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-159","question":"Under Article 133(3), unless Parliament by law provides otherwise, an appeal to the Supreme Court does NOT lie from:","options":["a judgment of a single judge of a High Court","a judgment of a Division Bench in a civil case","a High Court judgment certified under Article 134A","a High Court order reversing an acquittal and imposing a death sentence"],"answer":0,"explanation":"Article 133(3) bars appeals from a single judge's decision; such decisions go first to a Division Bench of the High Court. The death-sentence case is an appeal as of right under Article 134.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-160","question":"The Supreme Court began with the Chief Justice and seven other judges. The Supreme Court (Number of Judges) Act, 1956, the first such increase, raised the total strength including the Chief Justice to:","options":["8","11","14","18"],"answer":1,"explanation":"The 1956 Act added three judges, for a total of 11. Later laws raised the total to 14 (1960), 18 (1977) and then further.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-161","question":"Consider the following statements: 1. Article 32(4) says the right to move the Supreme Court shall not be suspended except as provided by the Constitution. 2. During a National Emergency, the President may suspend the right to move any court for the enforcement of Article 21. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Article 32 can be suspended only through Article 359, and since the 44th Amendment an Article 359 order cannot cover Articles 20 and 21. Statement 2 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-162","question":"As ‘master of the roster’ in the Supreme Court, who constitutes benches and allocates cases to them?","options":["The collegium of the five senior-most judges","The Registrar General","The full court, by vote","The Chief Justice of India"],"answer":3,"explanation":"The Court has affirmed (in 2017–18 rulings) that the CJI alone holds this administrative power, as first among equals.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-163","question":"In which case did the Supreme Court treat a letter from a prisoner, complaining of torture of a fellow prisoner, as a habeas corpus petition?","options":["Maneka Gandhi v. Union of India","Sunil Batra v. Delhi Administration","Hussainara Khatoon v. State of Bihar","M. C. Mehta v. Union of India"],"answer":1,"explanation":"Sunil Batra (II) (1980) is a landmark of epistolary jurisdiction. Hussainara Khatoon arose from newspaper reports on undertrial prisoners.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-164","question":"Consider the following statements: 1. The administrative expenses of the Supreme Court, including the salaries and pensions of its staff, are charged on the Consolidated Fund of India. 2. Fees collected by the Supreme Court form part of the Consolidated Fund of India. 3. The administrative expenses of a High Court, including staff pensions, are charged on the Consolidated Fund of India. Which of the above are correct?","options":["1 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Article 146(3) supports 1 and 2. Under Article 229(3), a High Court's administrative expenses are charged on the State's Consolidated Fund.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-165","question":"Consider the following statements: 1. India has a single integrated judiciary that enforces both Union and State laws, unlike the dual system of the USA. 2. The High Courts are under the administrative control of the Supreme Court. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"The Supreme Court hears appeals from High Courts but does not control them administratively. High Courts are independent constitutional courts and control the subordinate courts themselves.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-166","question":"A district judge is called a ‘Sessions Judge’ when he:","options":["sits on the administrative side of the High Court","presides over a Lok Adalat","hears appeals from revenue courts","deals with criminal cases"],"answer":3,"explanation":"The same officer hears civil cases as District Judge and criminal cases as Sessions Judge, with power to try serious offences.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-167","question":"In the Cauvery Water Disputes Tribunal reference (1991), what did the Supreme Court say about its advisory jurisdiction under Article 143?","options":["A reference on a matter affecting a State can be made only with that State's consent","The President cannot use Article 143 to have it reconsider a decided question","It is bound to answer every reference made to it under Article 143(1)","A reference may be used to review a decided case if the Union so requests"],"answer":1,"explanation":"The Court held that Article 143 is not an appellate or review power over its own decisions. Nor does the Constitution require any State's consent for a reference.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-168","question":"In Union Carbide Corporation v. Union of India (1991), upholding the Bhopal gas settlement, the Supreme Court said of its power under Article 142 that:","options":["Ordinary statutory limits do not bind it, though it must respect fundamental public policy","It can be used only in criminal appeals and never in civil disputes between parties","It is subject to every provision of the Code of Civil Procedure, like any civil court's power","It can be exercised only on a reference made by the President under Article 143"],"answer":0,"explanation":"The Court held that prohibitions or limitations in ordinary laws do not as such limit its power under Article 142 to do complete justice, provided it does not contravene fundamental principles of public policy; on that basis it upheld the settlement.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-169","question":"In Supreme Court Bar Association v. Union of India (1998), the Court reviewed its earlier order in In re Vinay Chandra Mishra (1995), which had suspended an advocate's licence to practise for contempt. It held that:","options":["Article 129 lets the Court suspend an advocate's licence whenever it finds him guilty of contempt","Article 142 cannot supplant substantive law, so suspending a licence is for the Bar Council","Only Parliament, by a resolution of both Houses, can suspend an advocate's licence to practise","An advocate guilty of contempt can be punished only by the High Court where he is enrolled"],"answer":1,"explanation":"The Court held that Article 142 cannot be used to ignore express statutory provisions; suspending a licence for professional misconduct is for the Bar Council under the Advocates Act, though the Court may punish for contempt and bar the advocate from appearing before it until he purges the contempt.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-170","question":"In K. Veeraswami v. Union of India (1991), a former Chief Justice of a High Court was prosecuted for having assets beyond his known income. The Supreme Court held that:","options":["Judges of superior courts are immune from criminal prosecution, since only Parliament can remove them","A judge can be prosecuted only after Parliament has passed a removal motion against him","Judges are public servants under the anti-corruption law, but cases need the CJI's consultation","The anti-corruption law applies only to subordinate judges and not to High Court judges"],"answer":2,"explanation":"The majority held that High Court and Supreme Court judges are public servants under the Prevention of Corruption Act, 1947, but directed that no criminal case be registered against such a judge without first consulting the Chief Justice of India.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-171","question":"In C. Ravichandran Iyer v. Justice A. M. Bhattacharjee (1995), a Bar association had passed resolutions demanding a High Court Chief Justice's resignation. The Supreme Court:","options":["Upheld the Bar's right to force a judge to resign by boycotting his court indefinitely","Held that only Parliament may ever examine the conduct of a sitting High Court judge","Directed the Chief Justice of the High Court to resign within a period of thirty days","Held such resolutions improper and called for an in-house procedure for misconduct"],"answer":3,"explanation":"The Court held that Bar associations cannot coerce a judge into resigning, and that conduct falling short of impeachable misbehaviour needs an in-house procedure through the Chief Justices; the Supreme Court adopted such a procedure in 1999.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-172","question":"The Tribunals Reforms Act, 2021 abolished several appellate bodies and transferred their work to courts. Which of these was abolished by it?","options":["Intellectual Property Appellate Board","National Company Law Appellate Tribunal","Armed Forces Tribunal","Central Administrative Tribunal"],"answer":0,"explanation":"The Act abolished bodies such as the Intellectual Property Appellate Board, the Film Certification Appellate Tribunal and the Airport Appellate Tribunal, shifting their work mainly to the High Courts. The NCLAT, AFT and CAT continue, with only their service conditions now governed by the Act.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-173","question":"In Prakash Singh v. Union of India (2006), the Supreme Court issued directions on police reform. Which of these was among them?","options":["Merging all State police forces into one national police under the Union","Setting up a State Security Commission and a Police Establishment Board","Placing every police station under the direct control of the district judge","Electing the Director General of Police by the State Legislative Assembly"],"answer":1,"explanation":"The Court directed States to set up State Security Commissions, Police Establishment Boards and Police Complaints Authorities, give the DGP and field officers a minimum tenure, and separate investigation from law and order duties.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-174","question":"In State of Uttaranchal v. Balwant Singh Chaufal (2010), the Supreme Court addressed public interest litigation. What did it do?","options":["It abolished PIL and restored the strict rule that only an aggrieved person may sue","It held that PIL can be filed only by registered NGOs and not by individuals","It laid down guidelines to encourage genuine PILs and to curb frivolous or motivated ones","It held that a PIL may be filed only in the Supreme Court, and never before any High Court of a State"],"answer":2,"explanation":"Tracing the history of PIL, the Court asked High Courts to frame rules for PIL, to check the petitioner's credentials and bona fides, and to impose costs on petitions filed for oblique motives, while keeping PIL open for genuine causes.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-175","question":"In Central Public Information Officer, Supreme Court of India v. Subhash Chandra Agarwal (2019), a Constitution Bench held that:","options":["The judiciary is wholly outside the Right to Information Act to protect its independence","Judges' assets may be disclosed only with the consent of Parliament given by resolution","Only the Registry is covered by the RTI Act, and the Chief Justice's office is not","The office of the Chief Justice of India is a public authority under the RTI Act"],"answer":3,"explanation":"The Court held that the office of the CJI is part of the Supreme Court, a public authority under the RTI Act, so information such as judges' asset declarations can be disclosed, subject to the Act's exemptions; transparency and judicial independence go together.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-176","question":"In Swapnil Tripathi v. Supreme Court of India (2018), the Supreme Court accepted in principle:","options":["Live-streaming of hearings in cases of national importance","Conducting all of its hearings in Hindi instead of English","Allowing television cameras into judges' deliberations in chambers","Announcing each judge's vote in open court before writing judgments"],"answer":0,"explanation":"The Court held that live-streaming of proceedings, beginning with cases of constitutional and national importance, furthers open justice and access to justice; Constitution Bench hearings began to be streamed in 2022.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-177","question":"In P. Sambamurthy v. State of Andhra Pradesh (1987), the Supreme Court struck down the proviso to Article 371D(5), which let the State government modify or annul orders of the State Administrative Tribunal. Why?","options":["Because Article 371D was inserted without ratification by half the States","Because letting the executive override a tribunal's decision violates the rule of law","Because administrative tribunals may be set up only by Parliament under Article 323A itself","Because the proviso conflicted with the directive in Article 50 and nothing else"],"answer":1,"explanation":"The Court held that letting the government, itself a party, set aside the tribunal's decisions offended the rule of law and effective judicial review, both basic features, so the proviso fell even though it had been added by a constitutional amendment.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-178","question":"In Union of India v. R. Gandhi, President, Madras Bar Association (2010), on the National Company Law Tribunal, the Supreme Court held that:","options":["Parliament can never move any part of the jurisdiction of the High Courts to tribunals at all","Tribunals may be staffed entirely by civil servants if Parliament so decides by law","Tribunals replacing courts must have judicial members and independence like those courts","The NCLT is unconstitutional because company law falls in the State List"],"answer":2,"explanation":"The Court upheld Parliament's power to create the NCLT and its appellate tribunal, but held that a tribunal taking over court work must keep judicial independence and standards, and struck down provisions on qualifications and selection that fell short.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-179","question":"The Judicial Standards and Accountability Bill, 2010, which proposed a National Judicial Oversight Council to examine complaints against judges, finally:","options":["Became law in 2012 and replaced the Judges (Inquiry) Act, 1968","Was struck down by the Supreme Court along with the NJAC Act","Became law but was never notified in the Gazette by the Union government","Lapsed on the dissolution of the 15th Lok Sabha without being enacted"],"answer":3,"explanation":"The Lok Sabha passed the Bill in 2012, but it lapsed when the 15th Lok Sabha was dissolved in 2014 before the Rajya Sabha could pass it; the Judges (Inquiry) Act, 1968 still governs removal inquiries.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-180","question":"The ‘Restatement of Values of Judicial Life’, a code of conduct for judges, was adopted by:","options":["A full court meeting of the Supreme Court in 1997","Parliament through an amendment to the Judges (Inquiry) Act","The Bar Council of India under the Advocates Act, 1961","The Law Commission in a report on judicial reforms in 2008"],"answer":0,"explanation":"The full court of the Supreme Court adopted the Restatement in May 1997, and a Chief Justices' Conference endorsed it in 1999. It is a self-regulatory code, not a law.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-181","question":"In Indira Jaising v. Supreme Court of India (2017), the Supreme Court laid down a system for designating senior advocates. What did it create?","options":["A rule that every advocate becomes senior after 20 years of practice","A permanent committee, headed by the Chief Justice, using a points-based assessment","An election by the Bar Council of India from among all enrolled advocates","A written examination for the senior title, to be conducted by the Supreme Court itself"],"answer":1,"explanation":"The Court set up a Permanent Committee for Designation of Senior Advocates, chaired by the CJI with two senior judges, the Attorney General and a member of the Bar, to assess candidates on a points system before the full court decides.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-182","question":"Since the 54th Amendment (1986), how are the salaries of Supreme Court and High Court judges fixed?","options":["By an order of the President issued after consulting the Chief Justice of India","Only by a constitutional amendment to the Second Schedule each time","By Parliament by law, with the Second Schedule applying until such law is made","By the Finance Commission in its report once every five years"],"answer":2,"explanation":"The 54th Amendment changed Articles 125 and 221 so that judges' salaries are determined by Parliament by law, the Second Schedule figures applying only until then. Salaries cannot be varied to a judge's disadvantage after appointment, except in a Financial Emergency.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-183","question":"In Pritam Singh v. The State (1950), one of its earliest judgments, the Supreme Court explained how it would use the power under Article 136 to grant special leave in criminal cases. It said it would:","options":["Grant leave in every case where a sentence of imprisonment has been imposed","Re-examine the evidence in every appeal as if it were the trial court","Grant leave only where the High Court has certified the case as fit","Interfere only in exceptional cases, where grave injustice has been done"],"answer":3,"explanation":"The Court held that Article 136 gives a wide discretion to be used sparingly and only in exceptional cases, such as where substantial and grave injustice has been done; it is not a regular appeal against every conviction, and no High Court certificate is needed.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-184","question":"How many of these Supreme Court decisions were given on a Presidential reference under Article 143? I. The Third Judges case (1998) on the collegium II. In re Keshav Singh (1965) on legislative privilege III. The opinion on allocation of natural resources (2012) IV. Kesavananda Bharati v. State of Kerala (1973)","options":["Only three","Only two","All four","Only one"],"answer":0,"explanation":"The Third Judges case, Keshav Singh and the 2012 opinion on natural resources (sought after the 2G judgment) were all references under Article 143(1). Kesavananda was decided on writ petitions under Article 32.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-185","question":"In its 2012 opinion on the allocation of natural resources, given after the 2G spectrum judgment, the Supreme Court said that:","options":["Auction is the only constitutionally permissible way to allocate any natural resource at all","Auction is not a constitutional mandate for every resource, though allocation must be fair","Allocation of natural resources is a policy matter wholly outside judicial review","Only Parliament, by a resolution of both Houses, may allocate natural resources"],"answer":1,"explanation":"The Court held that auction is not constitutionally required for all natural resources; whatever method is chosen must be fair, non-arbitrary and for the common good under Articles 14 and 39(b), and remains open to judicial review.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-186","question":"How many of these statements about increases in the strength of the Supreme Court, counting the Chief Justice, are correct? I. It rose to 14 in 1960. II. It rose to 26 in 1986. III. It rose to 31 in 2009.","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Through amendments to the Supreme Court (Number of Judges) Act, 1956 the strength went from 11 (1956) to 14 (1960), 18 (1977), 26 (1986), 31 (2009) and 34 (2019), so all three are correct.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-187","question":"In Andi Mukta Sadguru Trust v. V. R. Rudani (1989), teachers of a college run by a private trust sought their unpaid dues. The Supreme Court held that a writ of mandamus:","options":["Can never issue to a private trust, which must be sued in a civil court","Can issue only if the trust has first been declared ‘State’ under Article 12","Can issue only to bodies created by a statute and not to registered trusts","Can issue to any body performing a public duty, even a private trust"],"answer":3,"explanation":"The Court held that ‘any person or authority’ in Article 226 is wider than ‘State’ in Article 12, so mandamus can issue to a private body performing a public duty such as running an aided college.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-188","question":"In Radhey Shyam v. Chhabi Nath (2015), a three-judge bench of the Supreme Court overruled part of Surya Dev Rai (2003). It held that judicial orders of civil courts:","options":["Are not open to writs under Article 226, but can be corrected under Article 227","Can be quashed by certiorari under Article 226 like the orders of any tribunal","Can be challenged only by special leave in the Supreme Court under Article 136","Are final, and no High Court may correct them under any Article of the Constitution"],"answer":0,"explanation":"The bench held that judicial orders of civil courts are not amenable to certiorari under Article 226, since such courts are not authorities to be corrected by writ, but the High Court's supervisory jurisdiction under Article 227 remains available.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-189","question":"In Bandhua Mukti Morcha v. Union of India (1984), the State objected to the Supreme Court appointing commissioners to inquire into bonded labour in stone quarries. The Court held that under Article 32 it:","options":["Can act only on affidavits and cannot gather facts through its own commissioners","Can appoint commissioners to find facts, as Article 32 is not tied to adversarial procedure","Can appoint commissioners only if the State government concerned first agrees to their appointment","Must send all fact-finding to the High Court of the State concerned in such cases"],"answer":1,"explanation":"Justice Bhagwati held that Article 32 prescribes no particular procedure, so in PIL the Court may appoint socio-legal commissions to gather facts; their reports serve as evidence, open to objection by the parties.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-190","question":"In Kanu Sanyal v. District Magistrate, Darjeeling (1974), the Supreme Court considered whether a writ of habeas corpus requires the detenu to be physically produced in court. It held that:","options":["Physical production of the body is an essential condition of every habeas corpus writ","Habeas corpus can issue only from the High Court within whose limits the person is held","Production of the body is not essential to decide the legality of the detention","Habeas corpus cannot be issued once the detenu has been moved to another State"],"answer":2,"explanation":"The Court held that the essence of habeas corpus is an inquiry into the legality of detention; bringing the person physically before the court is not indispensable, and the court may decide on the record.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-191","question":"In In re Arundhati Roy (2002), the Supreme Court held the writer guilty of contempt over statements in her reply to an earlier contempt notice. What sentence did it impose?","options":["Six months' simple imprisonment with no option of a fine","A ban on publishing any writing about the courts for a year","A fine of ₹1 only, with no term of imprisonment at all","Simple imprisonment for one day and a fine of ₹2,000"],"answer":3,"explanation":"Holding that her affidavit scandalised the Court, it imposed a symbolic one day's simple imprisonment and a fine of ₹2,000, with three months' imprisonment in default. The ₹1 fine was the 2020 Prashant Bhushan case.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-192","question":"In 2017 a seven-judge bench of the Supreme Court sentenced Justice C. S. Karnan of the Calcutta High Court for contempt. What was notable about this?","options":["He was the first sitting High Court judge jailed for contempt of court","He was removed from office by Parliament on the same day as the sentence","The Court ordered his removal from office using its power under Article 142","The President pardoned him before the sentence could be carried out"],"answer":0,"explanation":"The bench sentenced him to six months' imprisonment, the first such punishment of a sitting High Court judge. It could not remove him, since removal needs the parliamentary process under Articles 124(4) and 218.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-193","question":"Which Chief Justice of India resigned in 1967 to contest the election to the office of President?","options":["M. Hidayatullah","K. Subba Rao","P. B. Gajendragadkar","A. K. Sarkar"],"answer":1,"explanation":"Chief Justice K. Subba Rao, who wrote the majority judgment in Golaknath, resigned in April 1967 to contest the presidential election, which Zakir Husain won. Hidayatullah later acted as President in 1969 while he was CJI.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-194","question":"In All India Judges' Association v. Union of India (1993), the Supreme Court gave directions on the service conditions of the subordinate judiciary. Which of these was among them?","options":["Abolishing the posts of civil judge, leaving only district judges","Placing subordinate judges under the State Law Department's control","Raising the retirement age of judicial officers to 60 years","Requiring all subordinate judges to be recruited through the UPSC"],"answer":2,"explanation":"The Court directed a retirement age of 60 for judicial officers, subject to assessment of their fitness, and separate service conditions, which led to the First National Judicial Pay Commission under Justice K. J. Shetty.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-195","question":"In S. P. Gupta v. Union of India (1981), the government claimed privilege over its correspondence with the Chief Justice of India and others about the appointment and transfer of judges. The Supreme Court:","options":["Upheld the claim, holding such correspondence absolutely privileged","Held that only the President could decide whether to disclose it","Referred the question to Parliament under its rules on privileges","Rejected the claim and ordered disclosure, citing open government"],"answer":3,"explanation":"The Court held that the right to know flows from Article 19(1)(a) and disclosure is the rule; privilege applies only where disclosure would really harm the public interest, which was not shown, so the correspondence was disclosed.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-196","question":"In Special Reference No. 1 of 1964 (the Keshav Singh case), the Uttar Pradesh Assembly had ordered two High Court judges to be brought before it for granting bail to a man it had jailed for contempt. The Supreme Court opined that:","options":["The High Court could hear the habeas corpus plea, and the Assembly could not punish its judges","The Assembly's privilege under Article 194(3) is absolute and is beyond review by any court of law","Only the Supreme Court, and not a High Court, may examine a committal by a legislature","The Assembly could punish the judges but not the advocate who had filed the petition"],"answer":0,"explanation":"The Court held that legislative privileges are subject to the Constitution, so the High Court could entertain a habeas corpus petition against a committal by the House, and the judges who did so were not guilty of contempt of the Assembly.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-197","question":"Which of these has the Supreme Court held is NOT part of the basic structure of the Constitution?","options":["Judicial review under Articles 32 and 226","The right to property under Article 300A","Free and fair elections","Independence of the judiciary"],"answer":1,"explanation":"In Jilubhai Nanbhai Khachar (1995) the Court held that the right to property under Article 300A is not part of the basic structure. Judicial review (Minerva Mills, L. Chandra Kumar), free and fair elections (Indira Gandhi v. Raj Narain) and judicial independence (the NJAC case) are.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-198","question":"In State of Rajasthan v. Union of India (1977), several States challenged the Union government's move to have their Assemblies dissolved after the Lok Sabha elections. The Supreme Court:","options":["Struck down the dissolutions as mala fide and restored all the dissolved State Assemblies at once","Held that a State can never sue the Union under Article 131 on such a matter","Dismissed the suits, declining to interfere with the President's satisfaction under Article 356","Referred the dispute to the Inter-State Council under Article 263 for its decision"],"answer":2,"explanation":"The Court entertained the suits under Article 131 but dismissed them, holding that it could not interfere with the President's satisfaction on the facts shown. S. R. Bommai (1994) later widened judicial review of Article 356.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-199","question":"How many of these were done by the Supreme Court invoking Article 142? I. Directing the allotment of five acres for a mosque in the Ayodhya judgment (2019) II. Declaring the right to privacy a fundamental right (2017) III. Holding that it may dissolve a marriage on the ground of irretrievable breakdown (2023) IV. Striking down the 99th Amendment on judicial appointments (2015)","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III rested on the power to do complete justice under Article 142. The privacy ruling (Puttaswamy) interpreted Articles 14, 19 and 21, and the NJAC ruling was judicial review of an amendment, not Article 142.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-200","question":"In K. Ashok Reddy v. Government of India (1994), on transfers of High Court judges under Article 222, the Supreme Court held that:","options":["No High Court judge can be transferred without first obtaining his own written consent","Every transfer must first be approved by a resolution of both Houses of Parliament","A transfer is punitive in nature, so an inquiry must be held before it is made","Judicial review is confined to whether the transfer followed the CJI's recommendation"],"answer":3,"explanation":"Following the Second Judges case, the Court held that transfers are made in the public interest on the recommendation of the CJI after due consultation, so judicial review is limited to whether that procedure was followed; the judge's consent is not needed.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-201","question":"ADM Jabalpur v. Shivkant Shukla (1976), which had denied habeas corpus during the Emergency, was expressly declared wrongly decided and overruled in:","options":["K. S. Puttaswamy v. Union of India (2017)","Maneka Gandhi v. Union of India (1978)","Minerva Mills Ltd. v. Union of India (1980)","S. R. Bommai v. Union of India (1994)"],"answer":0,"explanation":"The nine-judge bench in Puttaswamy (2017) held that ADM Jabalpur was seriously flawed and expressly overruled it, affirming that life and personal liberty are inalienable. The 44th Amendment had earlier barred suspension of Articles 20 and 21.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-202","question":"Under the Supreme Court Rules, who alone is entitled to file an appearance and act for a party in the Supreme Court?","options":["Any Senior Advocate designated by the Court","An Advocate-on-Record","Any advocate with ten years' standing at the Bar","The Attorney General or the Solicitor General"],"answer":1,"explanation":"Only an Advocate-on-Record, who has passed the Court's examination and meets its conditions, can file matters and act for a party; other advocates, including senior advocates, can argue only on the instructions of an Advocate-on-Record.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-203","question":"The power of courts to strike down laws that conflict with the Constitution, known as judicial review, is traced to which judgment of the US Supreme Court?","options":["McCulloch v. Maryland (1819)","Gibbons v. Ogden (1824)","Marbury v. Madison (1803)","Brown v. Board of Education (1954)"],"answer":2,"explanation":"Chief Justice John Marshall's opinion in Marbury v. Madison (1803) established that courts can declare a law void for conflicting with the Constitution. In India judicial review rests on express provisions such as Articles 13, 32 and 226.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-204","question":"The Supreme Court of Judicature at Fort William in Calcutta, set up in 1774 under the Regulating Act, 1773, had as its first Chief Justice:","options":["William Jones","Robert Chambers","Warren Hastings","Elijah Impey"],"answer":3,"explanation":"Sir Elijah Impey was the first Chief Justice of the Calcutta Supreme Court, with Chambers, Lemaistre and Hyde as puisne judges. Warren Hastings was the Governor-General, and William Jones joined the court later.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-205","question":"Which statement about a High Court's power to punish for contempt is correct?","options":["It can punish contempt of itself and of the courts subordinate to it","It can punish contempt of itself only, never of a subordinate court","It can act only if the Advocate General files a contempt petition","It cannot punish a contempt committed outside its territorial limits"],"answer":0,"explanation":"Article 215 makes a High Court a court of record with power to punish contempt of itself, and the Contempt of Courts Act, 1971 also lets it punish contempt of subordinate courts, even if the contempt is committed outside its territorial limits. It may act on its own motion.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-206","question":"In E. M. S. Namboodiripad v. T. Narayanan Nambiar (1970), the former Kerala Chief Minister had described the judiciary as an instrument of class oppression. The Supreme Court held that:","options":["His remarks were political criticism and so protected absolutely by Article 19(1)(a)","Free speech does not shield remarks that lower courts' authority, so he was guilty","As a former Chief Minister he was immune from contempt proceedings under Article 361","Only the Kerala Assembly, and not a court, could act against him for such remarks"],"answer":1,"explanation":"The Court upheld his conviction for contempt, holding that freedom of speech under Article 19(1)(a) is subject to the law of contempt and does not protect statements that lower the authority of courts in the public eye; it reduced the fine.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-207","question":"The idea that Parliament's amending power has implied limits, argued by M. K. Nambyar in Golaknath and later shaped into the basic structure doctrine, drew on a 1965 lecture in India by:","options":["Ivor Jennings, a British constitutional scholar","Granville Austin, an American historian","Dieter Conrad, a German jurist","K. C. Wheare, an Australian-born scholar"],"answer":2,"explanation":"Dieter Conrad's lecture on implied limitations of the amending power, drawing on Germany's experience under the Weimar Constitution, was cited by Nambyar and influenced the Court's reasoning that culminated in Kesavananda (1973).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-208","question":"The Contempt of Courts Act, 1971 was based largely on the recommendations of a committee headed by:","options":["M. C. Setalvad","V. R. Krishna Iyer","K. Santhanam","H. N. Sanyal"],"answer":3,"explanation":"The H. N. Sanyal Committee (1961-63) studied the law of contempt and its recommendations shaped the 1971 Act, which defines civil and criminal contempt. K. Santhanam headed the committee on prevention of corruption.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-209","question":"How many of these statements about legal services institutions are correct? I. The Chief Justice of India is the Patron-in-Chief of the National Legal Services Authority. II. The Supreme Court Legal Services Committee is chaired by a sitting judge of the Supreme Court. III. The Chief Justice of the High Court is the Patron-in-Chief of the State Legal Services Authority.","options":["Only one","Only two","All three","None of them"],"answer":2,"explanation":"Under the Legal Services Authorities Act, 1987 the CJI is Patron-in-Chief of NALSA, a sitting Supreme Court judge chairs the Supreme Court Legal Services Committee, and the High Court's Chief Justice is Patron-in-Chief of the State authority. All three are correct.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-210","question":"Fast Track Courts to clear the backlog of sessions cases were first set up from 2000-01 on the recommendation of the:","options":["Eleventh Finance Commission","Law Commission in its Fourteenth Report","Malimath Committee on criminal justice","Second Administrative Reforms Commission"],"answer":0,"explanation":"The Eleventh Finance Commission recommended funds for about 1,700 Fast Track Courts, which began in 2000-01. The Malimath Committee reported only in 2003, and the Second ARC was set up in 2005.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-211","question":"The first Lok Adalat camp in India was held in 1982 in which State?","options":["Maharashtra","Gujarat","Tamil Nadu","Kerala"],"answer":1,"explanation":"The first Lok Adalat camp was organised in Gujarat in 1982, and the movement spread before the Legal Services Authorities Act, 1987 gave Lok Adalats statutory status.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-212","question":"Under Article 147, a ‘substantial question of law as to the interpretation of this Constitution’ is to be read as including questions on the interpretation of:","options":["Any Act of Parliament that amends a law on a Concurrent List subject","The rules of procedure made by either House of Parliament","The Government of India Act, 1935 and Indian Independence Act, 1947","Any treaty that India has signed and ratified with another country"],"answer":2,"explanation":"Article 147 says that references to a substantial question of law on interpreting the Constitution include questions on interpreting the Government of India Act, 1935, the Indian Independence Act, 1947 and orders made under them.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-213","question":"Under Article 134(1) itself, an appeal lies to the Supreme Court as of right in a criminal case where a High Court has: I. on appeal reversed an acquittal and sentenced the accused to death II. withdrawn a case from a subordinate court, tried it and sentenced the accused to death III. on appeal reversed an acquittal and sentenced the accused to imprisonment for life","options":["I, II and III","I and III only","II and III only","I and II only"],"answer":3,"explanation":"Article 134(1)(a) and (b) cover death sentences after reversing an acquittal or after withdrawing and trying a case. Appeals where a life sentence or ten years is imposed on reversal of acquittal come from the 1970 Act on enlarged criminal appellate jurisdiction, made under Article 134(2).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-214","question":"In Whirlpool Corporation v. Registrar of Trade Marks (1998), the Supreme Court said that an alternative remedy does not bar a writ under Article 226 in certain situations. Which of these is NOT one of them?","options":["The petitioner prefers the High Court because a writ is quicker","The petition seeks to enforce one of the Fundamental Rights in Part III","The order was passed in violation of natural justice","The proceedings are wholly without jurisdiction"],"answer":0,"explanation":"Whirlpool listed enforcement of a Fundamental Right, violation of natural justice, action wholly without jurisdiction and a challenge to the vires of an Act as cases where the alternative remedy rule does not apply. Mere convenience or speed is not an exception.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-215","question":"In Om Kumar v. Union of India (2001), the Supreme Court explained how courts review administrative action. It held that where such action restricts the freedoms under Article 19 or the right under Article 21, courts apply:","options":["Wednesbury unreasonableness alone, with courts acting only as secondary reviewers","Proportionality, acting as primary reviewers of the action","Strict scrutiny as developed by the United States courts","No review at all, since such action is a matter of policy"],"answer":1,"explanation":"The Court held that administrative action affecting fundamental freedoms is tested for proportionality, with courts as primary reviewers, while action challenged only as arbitrary under Article 14 is tested on Wednesbury principles, with courts as secondary reviewers.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-216","question":"From 1950 until it moved to its present building in 1958, the Supreme Court sat in:","options":["The Durbar Hall of Rashtrapati Bhavan","Hyderabad House on Ashoka Road in New Delhi","The Chamber of Princes in Parliament House","The Diwan-i-Aam of the Red Fort"],"answer":2,"explanation":"The Supreme Court, like the Federal Court before it, sat in the Chamber of Princes in the Parliament building until it moved to its own building on Tilak Marg in 1958.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-217","question":"The motto on the emblem of the Supreme Court of India, ‘Yato Dharmastato Jayah’, means:","options":["Truth alone triumphs","Justice delayed is justice denied","Righteousness protects those who protect it","Where there is dharma, there is victory"],"answer":3,"explanation":"The phrase, from the Mahabharata, means that victory lies where dharma (righteousness) is. ‘Truth alone triumphs’ is Satyameva Jayate, the national motto.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-218","question":"The Judges (Protection) Act, 1985 provides that:","options":["No court may hear a civil or criminal case against a judge over judicial acts","No judge can be transferred to another court without first giving his written consent","A judge's salary cannot be reduced even during a Financial Emergency","No judge can be arrested without the prior sanction of the President"],"answer":0,"explanation":"The Act bars courts from entertaining civil or criminal proceedings against a judge or magistrate for any act, thing or word done or spoken in the discharge of official or judicial duty, though the government's power to act against him otherwise is saved.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-219","question":"Who became, in 2018, the first woman to be appointed a judge of the Supreme Court directly from the Bar?","options":["R. Banumathi","Indu Malhotra","Ruma Pal","Sujata Manohar"],"answer":1,"explanation":"Indu Malhotra, a senior advocate, was elevated directly from the Bar in April 2018. Ruma Pal, Sujata Manohar and R. Banumathi had come to the Supreme Court from High Courts.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-judiciary-220","question":"In October 2017 the Supreme Court collegium took a decision to improve the transparency of the appointment process. What did it decide?","options":["To hand over appointments to the National Judicial Appointments Commission","To include the Union Law Minister as a full member of the collegium","To hold all of its meetings in open court with the Bar present","To publish its recommendations and reasons on the Supreme Court website"],"answer":3,"explanation":"The collegium resolved to upload its decisions on appointments and elevations, with reasons, to the Supreme Court website. The NJAC had been struck down in 2015, and the collegium remains a body of judges only.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-221","question":"The Committee on Reforms of the Criminal Justice System, which submitted its report in 2003, was headed by:","options":["V. S. Malimath","H. N. Sanyal","M. N. Venkatachaliah","B. N. Srikrishna"],"answer":0,"explanation":"Justice V. S. Malimath's committee recommended changes to criminal procedure and evidence. M. N. Venkatachaliah headed the National Commission to Review the Working of the Constitution, and H. N. Sanyal the earlier committee on contempt.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-judiciary-222","question":"Under the Contempt of Courts Act, 1971, which of these is civil contempt rather than criminal contempt?","options":["Publishing matter that scandalises or lowers the authority of a court","Publishing matter that interferes with the due course of a pending trial","Obstructing the administration of justice in any other manner","Wilful breach of an undertaking given to a court"],"answer":3,"explanation":"Civil contempt is wilful disobedience of a court's judgment, decree, order or writ, or wilful breach of an undertaking given to a court. Scandalising a court, prejudicing proceedings and obstructing justice are criminal contempt.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
];

